        java.log("[PICA-LOGIN] from info email=" + email);
      }
    } catch(e3) {}
  }
  if (!email || !password) {
    java.log("[PICA-LOGIN] no credentials");
    java.toast("请输入账号和密码");
    return false;
  }
  var path = "auth/sign-in";
  try {
    var h = JSON.parse(picaHeaders(path, "POST"));
    var opts = {headers: h, method: "POST", body: JSON.stringify({email: email, password: password})};
    var url = PICA_BASE + "/" + path + "," + JSON.stringify(opts);
    var resp = java.connect(url, null, 30000);
    var raw = resp && resp.body ? String(resp.body()) : "";
    java.log("[PICA-LOGIN] raw=" + raw.substring(0, 200));
    var json = JSON.parse(raw);
    if (json.code === 200 && json.data && json.data.token) {
      source.putLoginHeader("authorization: " + json.data.token);
      try { source.putLoginInfo(JSON.stringify({账号: email, 密码: password})); } catch(e4) {}
      java.log("[PICA-LOGIN] token saved");
      java.toast("登录成功");
      return true;
    } else {
      java.log("[PICA-LOGIN] login fail code=" + json.code);
      java.toast("登录失败: " + (json.message || "未知错误"));
      return false;
    }
  } catch(e) {
    java.log("[PICA-LOGIN] ERR " + e);
    java.toast("登录异常: " + e);
    return false;
  }
}

