const lang = 'https://m.qidian.com'

const qt = 'https://69.langge.tk'

function checkSourceUpdate(sourceId) {
    try {
        var java = this.java;
        var source = this.source;
        var vars = {};
        try { vars = JSON.parse(source.getVariable() || '{}'); } catch (e) {}
        if (!vars || typeof vars != 'object' || Array.isArray(vars)) vars = {};
        var now = Date.now();
        var lastCheck = Number(vars.sourceNoticeCheckedAt || 0);

        var raw = java.ajax(qt + '/source/api/manifest');
        var data = JSON.parse(raw || '{}');
        var info = data && data.code === 0 && data.data && data.data[sourceId];
        if (!info || !info.exists || !info.version) return;

        var configuredInterval = Number(data.check_interval_seconds);
        if (!isFinite(configuredInterval) || configuredInterval < 0) configuredInterval = 21600;
        var intervalMs = configuredInterval * 1000;
        if (lastCheck > 0 && now - lastCheck < intervalMs) return;

        var versions = vars.sourceNoticeVersions;
        if (!versions || typeof versions != 'object' || Array.isArray(versions)) versions = {};
        var current = String(info.version);
        var previous = String(versions[sourceId] || '');
        var pendingUpdate = previous && previous !== current;
        // 发现新版本后保留旧版本，直到用户点击“更新书源”确认处理，避免只提示一次。
        if (!pendingUpdate) {
            versions[sourceId] = current;
        }
        vars.sourceNoticeVersions = versions;
        vars.sourceNoticeCheckedAt = now;
        source.setVariable(JSON.stringify(vars));

        if (pendingUpdate) {
            java.longToast('书源已更新，请点击“更新书源”');
        }
    } catch (e) {
        // 更新提示失败不能影响发现页
    }
}


function generateCsrfToken() {
 let jsmy = String(this.cookie.getCookie(lang).match(/_csrfToken=([^;]*)/)?.[1] || '');
return jsmy;
}

function qdtoken() {
let qdtoken = String(this.cookie.getCookie(lang));
return qdtoken;
}

function isRequestCancelled(error) {
    var message = String(error || "");
    return /JobCancellationException|CancellationException|was cancelled|已取消|被取消/i.test(message);
}

function sourceAccessKey() {
    let key = "";
    try {
        let infoMap = this.source.getLoginInfoMap();
        if (infoMap && infoMap.get) {
            key = infoMap.get(String.fromCharCode(23494, 38053)) || "";
        }
    } catch (e) {}
