            } catch (e) {}
        }

        let cleanedContent = (content || '').replace(/\r/g, '').trim();
        let rawParagraphs = cleanedContent.split('\n');

        for (let i = 0; i < rawParagraphs.length; i++) {
            rawParagraphs[i] = rawParagraphs[i].trim();
        }

        // 正文段评按 paragraphId 索引，从1开始。
        for (let j = 0; j < commentList.length; j++) {
            let comment = commentList[j];
            let targetPId = Number(comment.paragraphId);
            let limitedTextCount = Number(comment.textCount || 0);


            if (targetPId > 0 && targetPId <= rawParagraphs.length && limitedTextCount > 0) {
