        }

        let result = [];
        for (let k = 0; k < rawParagraphs.length; k++) {
            result.push('<div rs-native>' + rawParagraphs[k] + '</div>');
        }
        return result.join('\n');
    } catch (e) {
        if (isRequestCancelled(e)) throw e;
        java.log(e);
        return content;
    }
}

