//初始化源变量
function sourceVariableDefaults() {
    return {
        "orderBy": "人气",
        "isfinish": "连载",
        "size": "全部",
        "sort": "🎆玄幻🎆",
        "dp": "1",
        "sp": "1",
        "say": "1",
        "img": "1"
    };
}

// 初始化并修复源变量，避免单个开关覆盖发现页筛选配置。
function csh() {
    var java = this.java;
    var source = this.source;
    var defaults = sourceVariableDefaults();
    var data = {};
    var changed = false;
    try {
        data = JSON.parse(source.getVariable() || "{}");
    } catch (e) {
        data = {};
        changed = true;
    }
    if (typeof data != "object" || data == null || Array.isArray(data)) {
        data = {};
        changed = true;
    }
    for (var key in defaults) {
        if (data[key] === undefined || data[key] === null) {
            data[key] = defaults[key];
            changed = true;
        }
    }
    // 清理旧书源/晴天书源遗留的筛选值，避免 type_dic[sort] 为空导致发现页降级。
    var allowed = {
        orderBy: ["人气", "时间", "字数", "收藏", "推荐", "点击"],
        size: ["全部", "30万以下", "30-50万", "50-100万", "100-200万", "200万以上"],
        isfinish: ["连载", "完本"],
        sort: ["🎆玄幻🎆", "🎆奇幻🎆", "🎆武侠🎆", "🎆仙侠🎆", "🎆都市🎆", "🎆现实🎆", "🎆军事🎆", "🎆历史🎆", "🎆游戏🎆", "🎆体育🎆", "🎆科幻🎆", "🎆悬疑🎆", "🎆诸天无限🎆", "🎆轻小说🎆", "🎆短篇🎆"]
    };
    for (var allowedKey in allowed) {
        if (allowed[allowedKey].indexOf(String(data[allowedKey])) < 0) {
            data[allowedKey] = defaults[allowedKey];
            changed = true;
        }
    }
    if (changed) {
        source.setVariable(JSON.stringify(data, null, 2));
    }
}

