                if (!qtkey) { java.toast("请点击登录，填写密钥后刷新章节"); return content; }
        var url=qt+'/chapter/god-comments?bookId='+bid+'&chapterId='+cid+'&key='+encodeURIComponent(qtkey)+'&device='+encodeURIComponent(deviceId||'');
