/* ============================================================================
 * 纯 JS 基础层 1：MD5 + AES-ECB 解密 + Base64
 * 目标：替换 java.md5Encode / java.aesBase64DecodeToString / java.base64Decode
 * 全部用位运算与 Uint8Array，不依赖任何宿主 API。
 * ==========================================================================*/

/* ---------------------------- MD5 ---------------------------- */
// 标准 MD5 实现，输入字符串（UTF-8），输出 32 位小写 hex
var JMMD5 = (function () {
  var S = [7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22,
           5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20,
           4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23,
           6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21];
  // K[i] = floor(2^32 * abs(sin(i+1)))
  var K = new Int32Array(64);
  (function () {
    for (var i = 0; i < 64; i++) K[i] = (Math.floor(Math.abs(Math.sin(i + 1)) * 4294967296)) | 0;
  })();

  // 字符串 -> UTF-8 字节
  function utf8Bytes(str) {
    var s = String(str), out = [], i, c;
    for (i = 0; i < s.length; i++) {
      c = s.charCodeAt(i);
      if (c < 0x80) out.push(c);
      else if (c < 0x800) { out.push(0xc0 | (c >> 6), 0x80 | (c & 63)); }
      else if (c >= 0xd800 && c < 0xdc00 && i + 1 < s.length) {
        // 代理对 -> 4 字节
        var c2 = s.charCodeAt(++i);
        var cp = 0x10000 + ((c - 0xd800) << 10) + (c2 - 0xdc00);
        out.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 63), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
      } else { out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63)); }
    }
    return out;
  }

  function rotl(x, c) { return (x << c) | (x >>> (32 - c)); }

  function md5(str) {
    var bytes = utf8Bytes(str);
    var len = bytes.length;
    // 补位：0x80，然后补 0 到 56 mod 64
    var withPad = bytes.slice();
    withPad.push(0x80);
    while (withPad.length % 64 !== 56) withPad.push(0);
    // 长度（比特，小端 64 位）
    var bitLen = len * 8;
    var lo = bitLen >>> 0, hi = Math.floor(bitLen / 4294967296) >>> 0;
    withPad.push(lo & 255, (lo >>> 8) & 255, (lo >>> 16) & 255, (lo >>> 24) & 255,
                 hi & 255, (hi >>> 8) & 255, (hi >>> 16) & 255, (hi >>> 24) & 255);

    var a0 = 0x67452301, b0 = 0xefcdab89, c0 = 0x98badcfe, d0 = 0x10325476;
    var M = new Int32Array(16);
    for (var off = 0; off < withPad.length; off += 64) {
      for (var j = 0; j < 16; j++) {
        M[j] = withPad[off + j * 4] | (withPad[off + j * 4 + 1] << 8) |
               (withPad[off + j * 4 + 2] << 16) | (withPad[off + j * 4 + 3] << 24);
      }
      var A = a0, B = b0, C = c0, D = d0, f, g, i;
      for (i = 0; i < 64; i++) {
        if (i < 16) { f = (B & C) | (~B & D); g = i; }
        else if (i < 32) { f = (D & B) | (~D & C); g = (5 * i + 1) % 16; }
        else if (i < 48) { f = B ^ C ^ D; g = (3 * i + 5) % 16; }
        else { f = C ^ (B | ~D); g = (7 * i) % 16; }
        var tmp = D;
        D = C; C = B;
        B = (B + rotl((A + f + K[i] + M[g]) | 0, S[i])) | 0;
        A = tmp;
      }
      a0 = (a0 + A) | 0; b0 = (b0 + B) | 0; c0 = (c0 + C) | 0; d0 = (d0 + D) | 0;
    }
    function hex32(v) {
      var s = '';
      for (var k = 0; k < 4; k++) {
        var b = (v >>> (k * 8)) & 255;
        s += (b < 16 ? '0' : '') + b.toString(16);
      }
      return s;
    }
    return hex32(a0) + hex32(b0) + hex32(c0) + hex32(d0);
  }
  return { md5: md5, utf8Bytes: utf8Bytes };
})();

/* ---------------------------- Base64 ---------------------------- */
var JMB64 = (function () {
  var TBL = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  var REV = null;
  function build() {
    REV = new Int16Array(256);
    for (var i = 0; i < 256; i++) REV[i] = -1;
    for (var j = 0; j < 64; j++) REV[TBL.charCodeAt(j)] = j;
    REV['='.charCodeAt(0)] = -2;
  }
  // 解码为字节数组（容忍换行、URL-safe 字符、空白）
  function decode(str) {
    if (REV === null) build();
    var s = String(str), out = [], buf = 0, bits = 0, i, v;
    for (i = 0; i < s.length; i++) {
      var ch = s.charCodeAt(i);
      if (ch === 0x2d) ch = 0x2b;        // '-' -> '+'
      else if (ch === 0x5f) ch = 0x2f;   // '_' -> '/'
      if (ch <= 32) continue;            // 空白跳过
      v = REV[ch & 255];
      if (v === -1) continue;
      if (v === -2) break;               // '='
      buf = (buf << 6) | v; bits += 6;
      if (bits >= 8) { bits -= 8; out.push((buf >>> bits) & 255); }
    }
    return out;
  }
  function encode(bytes) {
    var s = '', i;
    for (i = 0; i + 2 < bytes.length; i += 3) {
      var n = (bytes[i] << 16) | (bytes[i + 1] << 8) | bytes[i + 2];
      s += TBL[(n >> 18) & 63] + TBL[(n >> 12) & 63] + TBL[(n >> 6) & 63] + TBL[n & 63];
    }
    var rem = bytes.length - i;
    if (rem === 1) { var n1 = bytes[i] << 16; s += TBL[(n1 >> 18) & 63] + TBL[(n1 >> 12) & 63] + '=='; }
    else if (rem === 2) { var n2 = (bytes[i] << 16) | (bytes[i + 1] << 8); s += TBL[(n2 >> 18) & 63] + TBL[(n2 >> 12) & 63] + TBL[(n2 >> 6) & 63] + '='; }
    return s;
  }
