/* 把 API 返回的列表转成阅读器条目（与书源原 jmcat 等价） */
function jmcat(o) {
  var out = [];
  try {
    var host = jmhost(), imgH = jmimg();
    // 封面单独请求所需的 header（阅读器图片请求会带上）
    var hdo = { 'user-agent': JMU, 'X-Requested-With': 'com.JMComic3.app' };
    var cont = o && o.content ? o.content : (o && o.list ? o.list : null);
    if (cont == null) return out;
    for (var i = 0; i < cont.length; i++) {
      var c = cont[i];
      var id = String(c.id == null ? '' : c.id);
      if (!id) continue;
      var name = String(c.name == null ? '未知标题' : c.name);
      var au = String(c.author == null ? '' : c.author);
      var cover = 'https://' + imgH + '/media/albums/' + id + '_3x4.jpg?v=1';
      var ep = c.latest_ep ? String(c.latest_ep) : '';
      out.push({
        name: name, author: au, aid: id,
        url: 'https://' + host + '/album?id=' + id,
        cover: cover, ep: ep
      });
    }
  } catch (e) {}
  return out;
}

/* 取列表对象里的作者/标签拼接 */
function jmjoin(arr) {
  if (arr == null) return '';
  var s = '';
  for (var i = 0; i < arr.length; i++) { s += (i ? ',' : '') + String(arr[i]); }
  return s;
}

/* HTML 转义 */
function jmesc(s) {
  var t = String(s == null ? '' : s);
  t = t.split('&').join('&amp;');
  t = t.split('<').join('&lt;');
  t = t.split('>').join('&gt;');
  t = t.split('"').join('&quot;');
  return t;
}

/* --------------------------- 详情页面板（含收藏） --------------------------- */
// 收藏夹列表：GET /favorite?page=1&folder_id=0&o=mr
function jmFolderList() {
  var r = jmget('/favorite?page=1&folder_id=0&o=mr');
  if (r == null || r.folder_list == null) return [];
  var out = [];
  for (var i = 0; i < r.folder_list.length; i++) {
    var f = r.folder_list[i];
    var fid = String(f.FID != null ? f.FID : (f['0'] != null ? f['0'] : ''));
    var fnm = String(f.name != null ? f.name : (f['2'] != null ? f['2'] : ('收藏夹' + (i + 1))));
    out.push({ fid: fid, name: fnm });
  }
  return out;
}

// 收藏一本书：POST /favorite  (aid=..&folder_id=..)
function jmFav(aid, fid) {
  if (!jmLogged() && !jmLogged()) { return false; }
  var ts = jmts();
  var body = 'aid=' + encodeURIComponent(aid) + '&folder_id=' + encodeURIComponent(fid || '0');
  var r = jmraw('https://' + jmhost() + '/favorite', { ts: ts }, body, 'POST');
  if (r == null) return false;
  var o = null; try { o = JSON.parse(r.body); } catch (e) { return false; }
  return o != null && o.code === 200;
}

/* --------------------------- 目录/正文的 id 提取 --------------------------- */
function jmAidOf(u) {
  var i = String(u).indexOf('id=');
  if (i < 0) return '';
  var t = String(u).substring(i + 3), j = 0;
  while (j < t.length) { var c = t.charAt(j); if (c >= '0' && c <= '9') j++; else break; }
  return t.substring(0, j);
}



function jmPathOf(u,key){
 var s=String(u||'');var i=s.indexOf(key);
 if(i<0)return null;
 return s.substring(i);
}
function jmPathOf2(u,keys){
 var s=String(u||'');
 var best=-1;
 for(var i=0;i<keys.length;i++){var p=s.indexOf(keys[i]);if(p>=0&&(best<0||p<best))best=p;}
 if(best<0)return null;
 return s.substring(best);
}
function jmErrItem(msg){
 return {name:String(msg),author:'',aid:'0',url:'https://'+jmhost()+'/album?id=0',cover:'',ep:''};
}
function jmItem(name,author,aid){
 return {name:String(name),author:String(author),aid:String(aid),url:'https://'+jmhost()+'/album?id='+aid,cover:'',ep:''};
}

