(function(){
 try{
  var p=jmPathOf(baseUrl,'/album');
  if(p==null){return String(JSON.stringify({name:'加载异常',author:'',tags:'',cover:'',toc:'',aid:'',views:'',lc:'',fav:false,desc:'详情地址无效'}));}
  var a=jmget(p);
  if(a==null||a.id==null){return String(JSON.stringify({name:'加载失败',author:'',tags:'',cover:'',toc:'',aid:'',views:'',lc:'',fav:false,desc:'获取失败，请重试或切换线路'}));}
  var id=String(a.id);
  var nl=String.fromCharCode(10);
  var host=jmhost();
  var imgH=jmimg();
  var au=jmjoin(a.author), tags=jmjoin(a.tags);
  var desc=String(a.description||'');
  var views=String(a.total_views||'');
  var cat=(a.category!=null)?String(a.category.title||''):'';
  var lc='';
  if(a.series!=null&&a.series.length){lc=String(a.series[a.series.length-1].name||'');}
  jmp('jmalb_'+id,JSON.stringify({id:id,name:String(a.name||''),author:au,tags:tags,series:(a.series||[]),desc:desc}));
  var info=desc;
  if(views.length)info+=nl+'观看: '+views;
  if(cat.length)info+=nl+'分类: '+cat;
  if(lc.length)info+=nl+'最新: '+lc;
  var folds=jmFolderList();
  info+=nl+nl+'--- 收藏夹 '+(a.is_favorite===true?'已收藏':'未收藏')+' ---'+nl;
  if(folds.length){
    for(var i=0;i<folds.length;i++){
      info+='<button onclick=\"jmDoFav(\''+jmesc(id)+'\',\''+jmesc(folds[i].fid)+'\',\''+jmesc(folds[i].name)+'\')\">＋'+jmesc(folds[i].name)+'</button> ';
    }
    info+=nl+'（移动端 API 不支持指定收藏夹，统一加入所选夹）';
  } else {
    info+='未登录或暂无收藏夹：请先到书源菜单登录';
  }
  var out={name:String(a.name||''),author:au,tags:tags,
           cover:'https://'+imgH+'/media/albums/'+id+'_3x4.jpg?v=1',
           toc:'https://'+host+'/album?id='+id,aid:id,views:views,lc:lc,
           fav:(a.is_favorite===true),desc:info};
  return String(JSON.stringify(out));
 }catch(e){
  return String(JSON.stringify({name:'加载异常',author:'',tags:'',cover:'',toc:'',aid:'',views:'',lc:'',fav:false,desc:String(e).substring(0,120)}));
 }
})()

