(function(){
 try{
  var pid=jmAidOf(baseUrl);
  if(!pid)return '章节地址无效';
  var c=jmget('/chapter?id='+pid);
  if(c==null)return '本章获取失败，请下拉重试或切换线路';
  var imgs=c.images||[];
  if(imgs.length<1)return '本章暂无图片或需要登录(章节可能被锁定)';
  var imgH=jmimg(),ts=jmts();
  var cl=String.fromCharCode(10);
  var html='';
  for(var i=0;i<imgs.length;i++){
   var n=String(imgs[i]);
   html+='<img src="https://'+imgH+'/media/photos/'+pid+'/'+n+'?v='+ts+'">'+cl;
  }
  return html;
 }catch(e){return '本章解析失败: '+String(e).substring(0,120);}
})()

