function timeAgo(timestamp) {
  if (!timestamp) return '';
  const now = Math.round(new Date() / 1000);
  const updateTimestamp = Math.round(new Date(String(timestamp).replace(/-/g, '/')) / 1000);
  if (isNaN(updateTimestamp)) return '';
  let diff = now - updateTimestamp;
  if (diff < 0) diff = 0;

  const minute = 60;
  const hour = minute * 60;
  const day = hour * 24;
  const month = day * 30;
  const year = month * 12;
  const years = year * 10;

  if (diff < 30) return '刚刚';
  if (diff < minute) return diff + '秒前';
  if (diff < hour) return Math.floor(diff / minute) + '分钟前';
  if (diff < day) return Math.floor(diff / hour) + '小时前';
  if (diff < month) return Math.floor(diff / day) + '天前';
  if (diff < year) return Math.floor(diff / month) + '个月前';
  if (diff < years) return Math.floor(diff / year) + '年前';
  return '超过十年前';
}

