/* ---------------- 响应解析（归一化成统一字段） ---------------- */
/* 统一 Book 对象：{ name, author, bookUrl, coverUrl, intro, kind, lastChapter, wordCount } */
function fqExNorm(d) {
  /* d 可能是 A/B（snake_case）或 C（camelCase） */
  var id = d.book_id || d.bookId || d.bookIdStr || '';
  if (!id) return null;
  var name = d.book_name || d.bookName || '';
  if (!name) return null;
  var cover = d.thumb_url || d.thumbUri || d.thumb_uri || d.cover || '';
  var kind = d.category || d.book_type || d.complete_category || '';
  if (d.publisher) kind = (kind ? kind + ' · ' : '') + d.publisher;
  if (d.progress) kind = (kind ? kind + ' · ' : '') + d.progress;
  return {
    name: String(name),
    author: String(d.author || ''),
    bookUrl: fqMarkA('book_id=' + id),
    coverUrl: String(cover),
    intro: String(d.abstract || d.bookAbstract || ''),
    kind: String(kind),
    lastChapter: String(d.last_chapter_title || d.lastChapterTitle || ''),
    wordCount: String(d.word_number || d.wordNumber || d.chapter_number || '')
  };
}
/* A 榜榜单：data.result[] */
function fqParseRank(body) {
  var j = fqJson(body); if (!j) return null;
  var r = ((j.data || {}).result) || [];
  return fqExMap(r);
}
/* B 分类：data.data[]；返回 {books, hasMore} */
function fqParseCate(body) {
  var j = fqJson(body); if (!j) return null;
  var d = j.data || {};
  var r = d.data || [];
  return { books: fqExMap(r), hasMore: !!d.has_more };
}
/* C 精选：data.list[] */
function fqParseSelect(body) {
  var j = fqJson(body); if (!j) return null;
  var r = ((j.data || {}).list) || [];
  return fqExMap(r);
}
/* 出版：data.publication_list[] */
function fqParsePublication(body) {
  var j = fqJson(body); if (!j) return null;
  var d = j.data || {};
  var r = d.publication_list || d.list || [];
  return { books: fqExMap(r), total: d.total_count || 0 };
}
function fqExMap(arr) {
  var out = [], i;
  for (i = 0; i < arr.length; i++) {
    var b = fqExNorm(arr[i]);
    if (b) out.push(JSON.stringify(b));
  }
  return out;
}
function fqJson(body) {
  try { return JSON.parse(String(body)); } catch (e) { return null; }
}

/* ============================================================================
 * 分类发现 · 与阅读 App 的对接层
 *
 * 阅读 App 的 explore 机制：
 *   exploreUrl 里的每一项 → 请求该 URL → 用 ruleExplore 解析书籍列表
