/* 统一的 explore URL 生成器：阅读 App 在求值时会注入 page 全局变量 */
function fqExploreUrl(kind, id, page, gender) {
  var p = Number(page) || 1;
  /* 把类型与参数编码进标记，解析时再取回（避免依赖 App 的 URL 变量替换差异） */
  if (kind === 'rank') return fqExMark('rank|' + id + '|' + p);
  if (kind === 'cate') return fqExMark('cate|' + id + '|' + p + '|' + (gender ? 1 : 0));
  if (kind === 'select') return fqExMark('select|' + id + '|' + p);
  if (kind === 'publication') return fqExMark('pub|' + p);
  return '';
}
function fqExMark(s) { return 'fanqie-explore:' + s; }
function fqExUnmark(s) {
  var m = String(s || '').match(/fanqie-explore:([^"'\s]+)/);
  return m ? m[1] : '';
}

/* 把标记翻译成真实请求 URL */
function fqExploreReq(mark, source) {
  /* mark 可能已去掉前缀（来自 fqExUnmark），也可能仍带前缀 */
  var s = fqExUnmark(mark) || String(mark || '');
  var p = s.split('|');
  var kind = p[0];
  if (kind === 'rank') return fqRankUrl(p[1], p[2]);
  if (kind === 'cate') return fqCateUrl(p[1], p[3] === '1', p[2], 30);
  if (kind === 'select') return fqSelectUrl(p[1], p[2]);
  if (kind === 'pub') return fqPublicationUrl(p[1]);
  return '';
}

/* 拉取并解析分类列表（含翻页判断） */
function fqExploreList(mark, source) {
  var reqUrl = fqExploreReq(mark, source);
  if (!reqUrl) return [];
  var body = fqHttpGet(reqUrl);
  var p = (fqExUnmark(mark) || String(mark || '')).split('|');
  var kind = p[0];
  var books = null, hasMore = false;
  if (kind === 'rank') {
    books = fqParseRank(body);
    var jr = fqJson(body);
    hasMore = !!(jr && (jr.data || {}).has_more);
  } else if (kind === 'cate') {
    var r = fqParseCate(body);
    if (r) { books = r.books; hasMore = r.hasMore; }
  } else if (kind === 'select') {
    books = fqParseSelect(body);
    hasMore = !!(books && books.length >= 10);
  } else if (kind === 'pub') {
    var rp = fqParsePublication(body);
    if (rp) { books = rp.books; hasMore = books.length >= 50; }
  }
  if (!books) return [];
  /* 把「还有下一页」信息挂到结果里（通过全局变量传给 nextTocUrl） */
  FQ_EX_HASMORE = hasMore;
  FQ_EX_PAGE = Number(p[2] || p[1] || 1);
  return books;
}

/* 阅读 App 会先请求 bookList 规则，再求 nextTocUrl。
 * 这里 nextTocUrl 根据上一次的 hasMore 决定是否给下一页标记。 */
var FQ_EX_HASMORE = false, FQ_EX_PAGE = 1, FQ_EX_KIND = 'rank', FQ_EX_ID = 0, FQ_EX_GENDER = 1;
function fqExploreNext(mark) {
  if (!FQ_EX_HASMORE) return '';
  var p = (fqExUnmark(mark) || String(mark || '')).split('|');
  var kind = p[0], id = p[1], page = Number(p[2] || p[1] || 1);
  var nextPage = (kind === 'rank' || kind === 'cate' || kind === 'select') ? page + 1 : page + 1;
  if (kind === 'rank') return fqExMark('rank|' + id + '|' + nextPage);
  if (kind === 'cate') return fqExMark('cate|' + id + '|' + nextPage + '|' + p[3]);
  if (kind === 'select') return fqExMark('select|' + id + '|' + nextPage);
  if (kind === 'pub') return fqExMark('pub|' + nextPage);
  return '';
}

/* 普通 GET（分类接口都是明文，不需要四神签名） */
function fqHttpGet(url) {
  var headers = {
    'User-Agent': FQ_EX_UA,
    'Accept': 'application/json, text/plain, */*'
  };
  return java.ajax(url + ',' + JSON.stringify({ method: 'GET', headers: headers, retry: 2 }));
}


/* ======== explore 解析入口（供 ruleExplore 调用）======== */
/* 阅读 App 在 explore 模式：baseUrl = exploreUrl 求值后的标记，result = 响应体。
 * 但它同时会把标记当作"真实 URL"；为保证拿到标记，这里做双向兼容。 */
function fqExploreListFromResult(result, baseUrl, source) {
  var mark = fqExUnmark(baseUrl);
  if (!mark) mark = fqExUnmark(result);
  /* result 为空（App 把 data: 标记当作 URL 直接返回了）时，自己去拉真实数据 */
  var body = result;
  if (!mark || !fqJson(body) || fqJson(body) === null) {
    var reqUrl = fqExploreReq(mark, source);
    if (reqUrl) body = fqHttpGet(reqUrl);
  }
  var p = mark.split('|');
  var kind = p[0];
  var books = null, hasMore = false;
  if (kind === 'rank') {
    books = fqParseRank(body);
    var jr = fqJson(body);
    hasMore = !!(jr && (jr.data || {}).has_more);
  } else if (kind === 'cate') {
    var rc = fqParseCate(body);
    if (rc) { books = rc.books; hasMore = rc.hasMore; }
  } else if (kind === 'select') {
    books = fqParseSelect(body);
    hasMore = !!(books && books.length >= 10);
  } else if (kind === 'pub') {
    var rp = fqParsePublication(body);
    if (rp) { books = rp.books; hasMore = books.length >= 50; }
  }
  FQ_EX_HASMORE = hasMore;
  return books || [];
}
function fqExploreNextUrl(baseUrl) {
  return fqExploreNext(baseUrl);
}

/* ======== 设备自动注册 + 自愈 ======== */
/* ============================================================================
 * 番茄书源 · 设备自动注册模块（纯 JS，无 Packages.java.* 依赖）
 *
 * 【为什么需要】
 *   内置设备号会失效。实测：同一个正文接口
 *     · 用内置设备  → HTTP 200 但 content-length: 0（服务端拒绝返回内容）
 *     · 用新注册设备 → HTTP 200 且返回真实密文
 *   所以书源首次使用（或内置设备失效）时，必须走一次 device_register 拿新设备。
 *
 * 【注册流程】（照搬番茄 App 的 ss_app_log 上报协议）
 *   POST https://log5-applog.fqnovel.com/service/2/device_register/?<query>
 *   返回 { device_id, install_id, device_token, new_user }
 * ==========================================================================*/

/* 常见机型池（与 App 上报的一致） */
var FQ_DEV_POOL = {
  HUAWEI: ['ELS-AN00', 'WLZ-AN00', 'ANA-AN00'],
  Xiaomi: ['24031PN0DC', '2304FPN6DC', '2201123C'],
  OPPO: ['CPH2207', 'CPH2371'],
  vivo: ['V2197A', 'V2073A']
};

function fqPickOne(a) { return a[Math.floor(Math.random() * a.length)]; }
function fqHexMd5(s) { return bytesHex(md5(utf8b(String(s)))); }
function fqUuid4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    var r = (16 * Math.random()) | 0;
    return (c === 'x' ? r : ((3 & r) | 8)).toString(16);
  });
}

/* 生成一套全新的设备参数（deviceId/iid 留空，等注册接口回填） */
function fqNewDevice() {
  var brands = Object.keys(FQ_DEV_POOL);
  var brand = fqPickOne(brands);
  var model = fqPickOne(FQ_DEV_POOL[brand]);
  var osv = fqPickOne(['12', '13', '14']);
  var osapi = { '12': '32', '13': '33', '14': '34' }[osv];
  /* androidId：16 位随机十六进制 */
  var androidId = '';
  for (var c = 0; c < 16; c++) androidId += '0123456789abcdef'.charAt(Math.floor(16 * Math.random()));
  /* openudid = md5(androidId) + md5(md5(androidId)).substr(0,8) —— 必须这样算，否则注册接口返回 device_id:0 */
  var h1 = fqHexMd5(androidId);
  var openudid = h1 + fqHexMd5(h1).substr(0, 8);

  var d = fqDefDevice();
  d.deviceBrand = brand;
  d.deviceType = model;
  d.osVersion = osv;
  d.osApi = osapi;
  d.androidId = androidId;
  d.openudid = openudid;
  d.cdid = fqUuid4();
  d.clientudid = fqUuid4();
  d.reqId = fqUuid4();
  d.deviceId = '';
  d.iid = '';
  return d;
}

/* 构造 device_register 的 ss_app_log 报文 */
function fqRegisterBody(dev, ts) {
  return {
    magic_tag: 'ss_app_log',
    _gen_time: ts,
    header: {
      display_name: '番茄小说', aid: 1967, channel: 'googleplay',
      package: 'com.dragon.read.oversea.gp',
      app_version: dev.versionName, version_code: parseInt(dev.versionCode),
      update_version_code: parseInt(dev.versionCode),
      manifest_version_code: parseInt(dev.versionCode),
      app_version_minor: dev.versionName,
      sdk_version: '3.7.0-rc.25-fanqie-xiaoshuo-opt',
      sdk_target_version: 29, git_hash: '5b6a0d3', sdk_flavor: 'china',
      guest_mode: 0, is_system_app: 0, pre_installed_channel: '', not_request_sender: 0,
      os: 'Android', os_version: dev.osVersion, os_api: parseInt(dev.osApi),
      device_model: dev.deviceType, device_brand: dev.deviceBrand,
      device_manufacturer: dev.deviceBrand, cpu_abi: 'arm64-v8a',
      release_build: 'V417IR_20171120',
      density_dpi: 480, display_density: 'xxhdpi', resolution: '1920x1080',
      language: 'zh', timezone: 8, access: 'wifi',
      rom_version: 'V417IR release-keys',
      cdid: dev.cdid, openudid: dev.openudid, clientudid: dev.clientudid,
      ipv6_list: [{ type: 'client_anpi', value: '::' }],
      region: 'CN', tz_name: 'Asia/Shanghai', tz_offset: 28800,
      sim_serial_number: [], oaid_may_support: false, req_id: dev.reqId,
      device_platform: 'android',
      custom: { host_bit: 64, account_region: 'cn', device_type: 'phone' },
      apk_first_install_time: ts - 2592e6
    }
  };
}

/* 执行 device_register，成功返回带 deviceId/iid 的设备对象，失败返回 null */
function fqRegisterDevice() {
  var dev = fqNewDevice();
  var ts = Date.parse(new Date());
  var qs = 'aid=1967&version_code=' + dev.versionCode
    + '&channel=googleplay&package=com.dragon.read.oversea.gp'
    + '&_rticket=' + ts + '&use_store_region_cookie=1'
    + '&okhttp_version=4.2.137.76-fanqie';
  var url = 'https://log5-applog.fqnovel.com/service/2/device_register/?' + qs;
  var headers = {
    'User-Agent': fqUa(dev),
    'Accept': 'application/json',
    'Content-Type': 'application/json',
    'Accept-Encoding': 'identity',
    'x-ss-req-ticket': String(ts),
    'x-vc-bdturing-sdk-version': '3.7.2.cn'
  };
  var spec = url + ',' + JSON.stringify({
    method: 'POST', headers: headers,
    body: JSON.stringify(fqRegisterBody(dev, ts)), retry: 1
  });
  var resp = '';
  try { resp = String(java.ajax(spec)); } catch (e) { return null; }
  if (!resp) return null;
  var j = null;
  try { j = JSON.parse(resp); } catch (e) { return null; }
  var d = (j && j.data && typeof j.data === 'object') ? j.data : j;
  if (!d) return null;
  var did = String(d.device_id || ''), iid = String(d.install_id || '');
  /* device_id 必须是纯数字且非 0，否则视为失败 */
  if (!/^\d+$/.test(did) || did === '0' || !/^\d+$/.test(iid) || iid === '0') return null;
  dev.deviceId = did;
  dev.iid = iid;
  if (d.device_token) dev.deviceToken = String(d.device_token);
  return dev;
}

/* 设备可用性自检：拿一本书的首章，看服务端是否下发密文（crypt_status=0 且 content 非 Invalid） */
function fqCheckDevice(dev) {
  try {
    var toc = java.ajax(fqSigned(
      'https://api5-normal-sinfonlineb.fqnovel.com/reading/bookapi/directory/all_items/v?'
      + fqQS(fqTocParams(dev)), dev, null, 'GET'));
    var chs = fqPickToc(toc);
    if (!chs || !chs.length) return false;
    var item = chs[0].item_id || chs[0].chapter_id;
    var book = (fqJson(toc) && (fqJson(toc).data || {}).book_id) || '';
    var c = fqPickChapter(java.ajax(fqSigned(
      'https://api5-normal-sinfonlineb.fqnovel.com/reading/reader/batch_full/v?'
      + fqQS(fqContentParams(dev, item, book)), dev, null, 'GET')));
    return !!(c && String(c.content) !== 'Invalid');
  } catch (e) { return false; }
}

/* ============================================================================
 * 设备自愈层：把设备注册接进 fqDevice / fqContent 的调用链
 *
 * 策略：
 *   1. fqDevice 优先用「缓存里的有效设备」→ 再回退内置设备
 *   2. fqContent 若发现服务端返回 content="Invalid"（=设备不被认可），
 *      自动注册新设备并重试一次，成功后写回缓存
 *   3. 提供 fqEnsureDevice() 供首次使用时主动激活
 * ==========================================================================*/

/* 源变量里存设备的键 */
var FQ_DEV_KEY = 'fqDeviceV1';

function fqLoadSavedDevice(source) {
  try {
    var v = fqVarGet(source);
    return (v && v[FQ_DEV_KEY]) ? v[FQ_DEV_KEY] : null;
  } catch (e) { return null; }
}
function fqSaveDeviceToSource(source, dev) {
  try {
    var v = fqVarGet(source);
    v[FQ_DEV_KEY] = dev;
    fqVarSet(source, v);
  } catch (e) {}
}

/* 取当前应使用的设备：缓存优先，否则内置 */
function fqActiveDevice(source) {
  var saved = fqLoadSavedDevice(source);
  if (saved && saved.deviceId && saved.iid) {
    return fqMerge(fqDefDevice(), saved);
  }
  return fqDefDevice();
}

/* 主动确保有一个可用设备：缓存有就直接用；没有就注册一个 */
function fqEnsureDevice(source, force) {
  if (!force) {
    var cached = fqLoadSavedDevice(source);
    if (cached && cached.deviceId && cached.iid) return cached;
  }
  var dev = fqRegisterDevice();
  if (dev) {
    fqSaveDeviceToSource(source, dev);
    return dev;
  }
  /* 注册失败：退回内置设备（至少还能搜书/看目录） */
  return fqDefDevice();
}

/* 设备被服务端拒绝时的自愈：注册新设备 + 清掉旧密钥缓存 */
function fqHealDevice(source) {
  var dev = fqRegisterDevice();
  if (!dev) return null;
  fqSaveDeviceToSource(source, dev);
  /* 旧密钥与新设备不匹配，必须清掉 */
  try {
    var v = fqVarGet(source);
    delete v.keys;
    delete v.device;
    fqVarSet(source, v);
  } catch (e) {}
  return dev;
}

/* --------- 供 fqContent 使用的包装：发现 Invalid 自动换设备重试 --------- */
function fqContentParams(dev, itemId, bookId) {
  var n = fqCommonParams(dev);
  n.item_ids = String(itemId);
  n.book_id = String(bookId);
  return n;
}
function fqTocParams(dev) {
  var n = fqCommonParams(dev);
  delete n.req_type; delete n.key_register_ts; delete n.compliance_status;
  n.book_type = '0'; n.book_id = ''; n.need_version = '1';
  return n;
}
/* 带自愈的章节获取：返回 {channel: 响应体, device: 实际使用的设备} */
function fqContentAuto(itemId, bookId, source) {
  var dev = fqActiveDevice(source);
  function fetch(device) {
    var url = 'https://api5-normal-sinfonlineb.fqnovel.com/reading/reader/batch_full/v?'
      + fqQS(fqContentParams(device, itemId, bookId));
    var spec = fqSigned(url, device, null, 'GET');
    /* 注意：fqFetch 的第一个参数必须是宿主 java（它内部要调 java.ajax） */
    return fqFetch(java, function () { return spec; },
      function (e) { return !!fqPickChapter(e); }, 3);
  }
  var body = fetch(dev);
  var ch = fqPickChapter(body);
  /* 服务端给了 Invalid 或空 → 设备不被认可，换新设备重试 */
  if (!ch || String(ch.content) === 'Invalid') {
    var healed = fqHealDevice(source);
    if (healed) body = fetch(healed);
  }
  return body;
}


/* ======== 正文 HTML 清理（番茄正文是 <article><blk> 结构）======== */
function fqCleanContent(html) {
  var s = String(html || '');

  /* ---- 1. 优先整段剥掉番茄自带的章节标题块 ---- */
  /* 结构：<h1 class="chapterTitle1" ...><blk ...>章节名</blk></h1> */
  s = s.replace(/<h1[^>]*class\s*=\s*["']?[^"'>]*chapterTitle[^"'>]*["']?[^>]*>[\s\S]*?<\/h1>/gi, '');
  /* 兜底：任何带 chapterTitle 字样的标签块 */
  s = s.replace(/<[^>]*chapterTitle[^>]*>[\s\S]*?<\/(?:h[1-6]|div|p|header)>/gi, '');

  /* ---- 2. 抽取正文主体 ---- */
  var m = s.match(/<article[^>]*>([\s\S]*?)<\/article>/i);
  if (m) s = m[1];
  /* 其余非正文结构 */
  s = s.replace(/<(header|footer|body|html)\b[^>]*>/gi, '')
       .replace(/<\/(header|footer|body|html)>/gi, '');
  s = s.replace(/<script[\s\S]*?<\/script>/gi, '')
       .replace(/<style[\s\S]*?<\/style>/gi, '');

  /* ---- 3. 段落标签转换行 ---- */
  s = s.replace(/<\s*(p|br|\/p|\/blk|\/h[1-6]|\/div|\/section|\/article)[^>]*>/gi, '\n');
  s = s.replace(/<\s*blk[^>]*>/gi, '');

  /* ---- 4. 剥掉剩余标签 ---- */
  s = s.replace(/<[^>]+>/g, '');

  /* ---- 5. 反转义实体 ---- */
  s = s.replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
       .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&');

  /* ---- 6. 规整空白 ---- */
  s = s.replace(/[ \t\u3000]+/g, ' ').replace(/\n{3,}/g, '\n\n');

  /* ---- 7. 逐段处理：去空行 + 缩进 + 去广告尾行 ---- */
  var parts = s.split('\n');
  var out = [];
  for (var i = 0; i < parts.length; i++) {
    var t = parts[i].replace(/^\s+|\s+$/g, '');
    if (!t) continue;
    /* 二次兜底：丢掉任何含广告特征的整行 */
    if (/倒卖|书源作者|Telegram|免费书源|请勿滥用|mtydfnl/i.test(t)) continue;
    out.push('　　' + t);
  }
  return out.join('\n');
}

/* ======== 剥掉番茄自带的章节标题块（必须在 fqParas 之前调用）========
 * 番茄正文首部结构：
 *   <h1 class="chapterTitle1" id="heading_id_2" idx="10000" p_idx="40000">
 *     <blk p_idx="10000" e_idx="0" e_order="0">章节名</blk>
 *   </h1>
 * 阅读 App 的标题栏已经会显示章节名，正文里重复出现一次没必要。 */
function fqStripChapterTitle(html) {
  var s = String(html || '');
  /* 主匹配：带 chapterTitle 类名的 h1~h6 整块 */
  s = s.replace(/<h[1-6][^>]*class\s*=\s*["']?[^"'>]*chapterTitle[^"'>]*["']?[^>]*>[\s\S]*?<\/h[1-6]>/gi, '');
  /* 兜底 1：任何标签里只要出现 chapterTitle 字样，连同其后第一个块级闭合标签一起删 */
  s = s.replace(/<[a-z][^>]*chapterTitle[^>]*>[\s\S]*?<\/(?:h[1-6]|div|p|header|section)>/gi, '');
  /* 兜底 2：剩余的裸 chapterTitle 容器（自闭合或结构异常） */
  s = s.replace(/<[a-z][^>]*chapterTitle[^>]*\/?>/gi, '');
  return s;
}

/* ======== 目录末章更新时间 ======== */
/* ============================================================================
 * 目录末章 · 更新时间标注
 *
 * 参考源的思路：把「最新章节的相对时间」拼到最后一条章节目录名上，例如
 *     我的26岁女房客 第1016集 殊途同归 · 3天前
 * 这样用户在目录里一眼就能看到这本书多久没更新了。
 *
 * 番茄接口提供两个时间戳（都是 Unix 秒）：
 *   · book_info.last_chapter_first_pass_time —— 书籍最后更新章节的时间（首选）
 *   · item_data_list[-1].first_pass_time    —— 末章自身的时间（兜底）
 * ==========================================================================*/

/* 相对时间描述（中文） */
function fqTimeAgo(ts) {
  var t = Number(ts) || 0;
  if (t <= 0) return '';
  var now = Math.floor(Date.now() / 1000);
  var diff = now - t;
  if (diff < 0) return '刚刚';
  if (diff < 60) return '刚刚';
  var m = 60, h = m * 60, d = h * 24, mo = d * 30, y = mo * 12;
  if (diff < m) return diff + '秒前';
  if (diff < h) return Math.floor(diff / m) + '分钟前';
  if (diff < d) return Math.floor(diff / h) + '小时前';
  if (diff < mo) return Math.floor(diff / d) + '天前';
  if (diff < y) return Math.floor(diff / mo) + '个月前';
  if (diff < y * 10) return Math.floor(diff / y) + '年前';
  return '超过十年前';
}

/* 绝对日期（yyyy-MM-dd），便于对照 */
function fqTimeAbs(ts) {
  var t = Number(ts) || 0;
  if (t <= 0) return '';
  var dt = new Date(t * 1000);
  var p = function (n) { return (n < 10 ? '0' : '') + n; };
  return dt.getFullYear() + '-' + p(dt.getMonth() + 1) + '-' + p(dt.getDate());
}

/* 从目录响应里取「最后更新时间」：优先 book_info，兜底末章 */
function fqTocUpdateTime(tocObj, chapters) {
  var t = 0;
  try {
    var bi = (tocObj && tocObj.data && tocObj.data.book_info) || {};
    t = Number(bi.last_chapter_first_pass_time) || 0;
  } catch (e) { t = 0; }
  if (!t && chapters && chapters.length) {
    var last = chapters[chapters.length - 1] || {};
    t = Number(last.first_pass_time) || 0;
  }
  return t;
}

/* 给「最后一条章节」的名字加上更新时间后缀。
 * chapters: fqPickToc 解析出的原始章节对象数组
 * tocObj  : 目录接口的原始响应（用于取 book_info） */
function fqAppendUpdateTime(items, tocObj) {
  if (!items || !items.length) return items;
  var t = fqTocUpdateTime(tocObj, items);
  if (!t) return items;
  var rel = fqTimeAgo(t);
  if (!rel) return items;
  /* 只标注最后一条 */
  var last = items[items.length - 1];
  if (!last || typeof last !== 'object') return items;
  var base = String(last.title || last.name || '');
  if (base.indexOf('· ' + rel) >= 0) return items;   /* 已标注过就不重复 */
  last.title = base + ' · ' + rel;
  if (last.name !== undefined) last.name = last.title;
  return items;
}

