}

function YuJianIsLongEggImage(data, url) {
  data = data || {};
  var width = Number(data.Width || data.ImgWidth || data.ImageWidth || data.PicWidth || data.width || 0);
  var height = Number(data.Height || data.ImgHeight || data.ImageHeight || data.PicHeight || data.height || 0);
  if (width > 0 && height > 0) return height / width >= 1.3;
  return /ccstatic[-.]|\/livemsg\//i.test(String(url || ''));
}

