  return { width: width, height: height };
}

function YuJianAppendEggImage(output, imageUrl, data, click) {
  var size = YuJianEggImageSize(data);
  var sliceHeight = Math.max(800, Math.floor((size.width || 640) * 2));
  var isLong = YuJianIsLongEggImage(data, imageUrl);
  if (isLong && size.width > 0 && size.height > sliceHeight) {
    var count = Math.ceil(size.height / sliceHeight);
    var separator = imageUrl.indexOf('?') >= 0 ? '&' : '?';
    for (var index = 0; index < count; index++) {
      var sliceUrl = imageUrl + separator + 'yujian_slice=' + index + '&yujian_slice_height=' + sliceHeight;
      var options = { style: 'FULL' };
      if (click) options.click = click;
      output.push('<img src="' + sliceUrl + ',' + JSON.stringify(options) + '">');
    }
    return;
  }
  var options = isLong ? { style: 'FULL' } : {};
  if (click) options.click = click;
  output.push('<img src="' + imageUrl + ',' + JSON.stringify(options) + '">');
}
