function YuJianEggMix(a, b, weight) {
  var x = YuJianEggRgb(a), y = YuJianEggRgb(b), out = '#';
  for (var i = 0; i < 3; i++) {
    var c = Math.round(x[i] * weight + y[i] * (1 - weight));
    out += (c < 16 ? '0' : '') + c.toString(16);
  }
  return out;
}

function YuJianEggAlpha(hex, alpha) {
  return 'rgba(' + YuJianEggRgb(hex).join(',') + ',' + alpha + ')';
}

function YuJianEggLuma(hex) {
  var c = YuJianEggRgb(hex);
  return (c[0] * 299 + c[1] * 587 + c[2] * 114) / 1000;
}

