function YuJianOpenEggVideo(url, title, cover, bookId, chapterId, videoIndex) {
  var ctx = this;
  var bridge = YuJianBridge(ctx);
  if (!bridge) return;
  url = String(url || '');
  title = String(title || '');
  cover = String(cover || '');
  if (!url || YuJianEggVideoExpired(url)) {
    var fresh = YuJianEggFreshVideo(ctx, bookId, chapterId, videoIndex);
    if (fresh && fresh.url) {
      url = fresh.url;
      cover = fresh.cover || cover;
      title = title || YuJianEggClickText(fresh.title);
    }
  }
  if (!url) {
    try { bridge.toast('彩蛋视频链接获取失败'); } catch (error) {}
    return;
  }

  // legado-E：内置播放器
  if (bridge.openVideoPlayer) {
    try {
      var options = { headers: { 'User-Agent': 'Dalvik/2.1.0 (Linux; U; Android 10; Build/UKQ1.230924.001)', referer: 'https://www.qidian.com' } };
      bridge.openVideoPlayer(url + ',' + JSON.stringify(options), '彩蛋章', false);
      return;
    } catch (error) {}
  }

  // 其他版本（MD3 等）：以起点域名为 baseUrl 加载 HTML5 播放页，WebView 会自动带上起点 Referer
  var html = YuJianEggVideoHtml(url, title, cover, YuJianEggTheme(ctx));
  var baseUrl = 'https://www.qidian.com/';
  if (bridge.showBrowser) {
    try {
      var sheetConfig = JSON.stringify({
        state: 3,
        isHideable: true,
        skipCollapsed: true,
        heightPercentage: 0.5,
        expandedCornersRadius: 20,
        dismissOnTouchOutside: true,
        widthPercentage: 1.0,
        maxWidth: -1,
        hardwareAccelerated: true,
        webViewInitialScale: 100
      });
      // preloadJs 非空时 MD3 才会注入 java 桥与屏幕方向等基础脚本；页面借此调整弹窗高度、全屏时撑满屏幕
      var preloadJs = 'window.YuJianEggConfig = function(config) { try { java.upConfig(JSON.stringify(config)); } catch (e) {} };';
      bridge.showBrowser(baseUrl, html, preloadJs, sheetConfig);
      return;
    } catch (error) {}
  }
  if (bridge.startBrowser) {
    try {
      bridge.startBrowser(baseUrl, '彩蛋章', html);
      return;
    } catch (error) {}
  }
  try { bridge.toast('当前阅读版本不支持视频播放'); } catch (error) {}
}

function YuJianEasterEggContent(ctx, bookId, chapterId) {
  var bridge = YuJianBridge(ctx);
  if (!bridge || !bookId || !chapterId) throw new Error('彩蛋章参数无效');
  var output = [];
  var videoIndex = 0;
  YuJianEggEachData(YuJianEggPages(ctx, bookId, chapterId), function(data) {
    var text = String(data.Text || '');
    if (text) output.push(text);
    var videoUrl = String(data.VideoUrl || '');
    var imageUrl = String(data.ImgUrl || data.VideoCoverUrl || '');
    if (!imageUrl && videoUrl) imageUrl = YuJianEggPlayCard(ctx);
    var click = '';
    if (videoUrl) {
      var args = [videoUrl, YuJianEggClickText(text), String(data.VideoCoverUrl || data.ImgUrl || ''), String(bookId), String(chapterId), videoIndex];
      click = 'YuJianOpenEggVideo(' + args.map(function(value) { return JSON.stringify(value); }).join(',') + ')';
      videoIndex++;
    }
    if (!imageUrl) return;
    YuJianAppendEggImage(output, imageUrl, data, click);
    if (videoUrl) output.push('点击图片播放视频。');
  });
  if (!output.length) throw new Error('彩蛋章内容为空');
  return output.join('\n');
}

// 本地直接请求起点获取本章说/段评摘要与作家说
function YuJianLocalReviewSummary(ctx, bookId, chapterId) {
  var bridge = YuJianBridge(ctx);
  var result = { counts: {}, hotComments: {}, chapter: 0, chapterEnd: 0, authorName: '', authorComments: '', authorSay: {}, endComments:[] };
  if (!bridge || !bookId || !chapterId) return result;

  var param = 'bookId=' + encodeURIComponent(String(bookId)) + '&chapterId=' + encodeURIComponent(String(chapterId));
  var activityUrl = YuJianQDSign('v1/assembly/getchapteractivity', param, ctx);
  var summaryUrl = YuJianQDSign('v1/chapterreview/getchapterrepagesummary', param + '&useImei=0&strategy=3', ctx);
  var endReviewUrl = YuJianQDSign('v1/chapterreview/getchapterendchapterreview', param + '&pg=1&pz=20', ctx);

  var res = [];
  try {
    if (bridge.ajaxAll) res = bridge.ajaxAll([activityUrl, summaryUrl, endReviewUrl]);
    else res = [bridge.ajax(activityUrl), bridge.ajax(summaryUrl), bridge.ajax(endReviewUrl)];
  } catch (e) {
    try { res = [bridge.ajax(activityUrl), bridge.ajax(summaryUrl)]; } catch (e2) {}
  }

  // 1. 解析段评数量汇总
  try {
    var rawSum = res[1] ? (typeof res[1].body === 'function' ? res[1].body() : res[1]) : '{}';
    var sumObj = JSON.parse(String(rawSum || '{}')).Data || {};
    var list = (sumObj.Getparagraphscommentcounts || {}).DataList || [];
    var reviews = sumObj.Reviews || [];
    for (var reviewIndex = 0; reviewIndex < reviews.length; reviewIndex++) {
      var review = reviews[reviewIndex];
      var reviewParagraphId = Number(review.ParagraphId);
      if (reviewParagraphId > 0 && review.Content && !result.hotComments[String(reviewParagraphId)]) {
        result.hotComments[String(reviewParagraphId)] = review;
      }
    }
    for (var i = 0; i < list.length; i++) {
      var item = list[i];
      var pid = Number(item.ParagraphId);
      var cnt = Number(item.CommentCount || item.TextCount || 0);
      if (pid === -1) {
        result.chapter = cnt;
      } else if (pid > 0 && cnt > 0) {
        result.counts[String(pid)] = { count: cnt, hot: Boolean(item.HasHotComment) };
      }
    }
  } catch (errSum) {}

  // 2. 解析作家说与末尾评论
  try {
    var rawAct = res[0] ? (typeof res[0].body === 'function' ? res[0].body() : res[0]) : '{}';
    var actObj = JSON.parse(String(rawAct || '{}')).Data || {};
    var actData = actObj.Getchapteractivity || {};
    result.authorSay = actData;
    result.authorName = String(actData.AuthorName || '');
    result.authorComments = String(actData.AuthorComments || '');

    var endCommentsObj = actObj.Getchapterendcomments || {};
    var endList = endCommentsObj.DataList || [];
    if (endCommentsObj.TotalCount) result.chapterEnd = Number(endCommentsObj.TotalCount);

    for (var k = 0; k < endList.length && k < 5; k++) {
      var c = endList[k];
      var txt = String(c.Content || '').replace(/https?:\/\/[^\s]+/g, '').replace(/["']/g, '');
      result.endComments.push({
        nickname: String(c.UserName || '书友'),
        content: txt,
        likeCount: Number(c.AgreeAmount || 0)
      });
    }
  } catch (errAct) {}

  // 3. 校验末尾章评数
  try {
    if (res[2]) {
      var rawEnd = typeof res[2].body === 'function' ? res[2].body() : res[2];
      var endData = JSON.parse(String(rawEnd || '{}')).Data || {};
      if (endData.TotalCount !== undefined) result.chapterEnd = Number(endData.TotalCount);
    }
  } catch (errEnd) {}

  return result;
}

// 降级使用服务端评论摘要接口
function YuJianServerReviewSummary(ctx, baseUrl) {
  var ids = YuJianIdsFromUrl(baseUrl);
  var result = { counts: {}, hotComments: {}, chapter: 0, chapterEnd: 0, authorName: '', authorComments: '', endComments:[] };
  if (!ids.bookId || !ids.chapterId) return result;
  var bridge = YuJianBridge(ctx);
  if (!bridge) return result;
  var token = YuJianCurrentToken(ctx, YuJianState(ctx));
  var options = YuJianRequestOptions(null, token);
  var url = YuJianApiUrl('/reviews/summary', ids) + ',' + JSON.stringify(options);
  try {
    var body = bridge.ajax(url);
    var resp = JSON.parse(String(body || '{}'));
    var data = resp.data || resp.Data || {};
    var paras = data.paragraphs || [];
    for (var i = 0; i < paras.length; i++) {
      var p = paras[i];
      var pid = Number(p.paragraphId);
      var cnt = Number(p.count || 0);
      if (pid === -1) {
        result.chapter = cnt;
      } else if (pid > 0 && cnt > 0) {
        result.counts[String(pid)] = { count: cnt, hot: Boolean(p.isHot) };
      }
    }
    var act = data.authorActivity || {};
    if (act.authorName || act.content) {
      result.authorName = String(act.authorName || '');
      result.authorComments = String(act.content || '');
    }
  } catch (err) {
    try {
      var fallbackUrl = YuJianApiUrl('/source/comments/counts', ids) + ',' + JSON.stringify(options);
      var fbBody = bridge.ajax(fallbackUrl);
      var fbResp = JSON.parse(String(fbBody || '{}'));
      result.counts = fbResp.counts || {};
      result.chapter = Number(fbResp.chapter || 0);
    } catch (fbErr) {}
  }
  return result;
}

