    var chars = raw.split(/(?![\uDC00-\uDFFF])/);
    if (chars.length > 18) raw = chars.slice(0, 18).join('') + '⋯';
    var content = YuJianEscapeXml(raw);
    var width = 1000, height = 120, boxHeight = 100;
    var padding = 32, tagWidth = 140, tagHeight = 56;
    var tagY = (boxHeight - tagHeight) / 2;
    var centerY = boxHeight / 2 + 14;
