      '<rect x="2" y="0" width="' + (width - 4) + '" height="' + boxHeight + '" fill="rgba(255,255,255,0.25)" rx="35" stroke="#888" stroke-width="1"/>' +
      '<rect x="' + padding + '" y="' + tagY + '" width="' + tagWidth + '" height="' + tagHeight + '" rx="20" fill="#FF4444"/>' +
      '<text x="' + (padding + tagWidth / 2) + '" y="' + centerY + '" font-size="32" fill="#FFF" text-anchor="middle" font-weight="bold">神评论</text>' +
      '<text x="' + (padding + tagWidth + 24) + '" y="' + centerY + '" font-size="38" fill="#000" font-weight="bold">' + content + '</text></svg>';
    var encoded = bridge && bridge.base64Encode ? bridge.base64Encode(svg) : java.base64Encode(svg);
    return YuJianSvgImage(encoded, {
      style: 'FULL',
