    if (rdc) {
      day.text = YuJianEggHex(rdc['textColor'], day.text);
      day.accent = YuJianEggHex(rdc['textAccentColor'], day.accent);
      night.text = YuJianEggHex(rdc['textColorNight'], night.text);
      night.accent = YuJianEggHex(rdc['textAccentColorNight'], night.accent);
      // 背景是图片时脚本读不到图（文件访问被 Rhino 拦截），改用中性纸色兜底；不混强调色以免偏色
      if (String(rdc['bgType']) === '0') day.bg = YuJianEggHex(rdc['bgStr'], '');
      if (String(rdc['bgTypeNight']) === '0') night.bg = YuJianEggHex(rdc['bgStrNight'], '');
    }
  } catch (error) {}
  var theme = {
    day: YuJianUiPalette(day.text, day.accent, day.bg, '#F6F0E4', '#2B2A28'),
    night: YuJianUiPalette(night.text, night.accent, night.bg, '#1D1C1B', '#E4E0DA')
