// ===== SVG 卡片工具 =====
function YuJianSvgChars(text) {
  return String(text || '').match(/[\uD800-\uDBFF][\uDC00-\uDFFF]|[\s\S]/g) || [];
}

// 按字形估算宽度（单位：字号倍数），CJK 记 1，拉丁字母数字约 0.55
function YuJianSvgCharWidth(ch) {
  var code = ch.charCodeAt(0);
  if (ch.length > 1) return 1.15;
  if (code === 0xFE0F || code === 0x200D || (code >= 0x0300 && code <= 0x036F)) return 0;
  if (code < 0x80) {
    if (ch === ' ') return 0.3;
    if (/[iljtfr.,:;'!|()\[\]]/.test(ch)) return 0.32;
    if (/[A-Z0-9mwMW@#%&]/.test(ch)) return /[mwMW@%]/.test(ch) ? 0.85 : 0.62;
    return 0.53;
  }
  if (code >= 0xFF61 && code <= 0xFF9F) return 0.55;
  return 1;
