  var out = '', width = fontSize;
  for (var i = 0; i < chars.length; i++) {
    var w = YuJianSvgCharWidth(chars[i]) * fontSize;
    if (width + w > maxWidth) break;
    out += chars[i];
    width += w;
  }
  return out.replace(/\s+$/, '') + '…';
}

// 按宽度换行；行首避开中文标点；超出 maxLines 时末行加省略号
function YuJianSvgWrap(text, fontSize, maxWidth, maxLines) {
  var noStart = '，。、；：！？）」』》】〉…—,.;:!?)]%';
  var lines = [];
  var paragraphs = String(text || '').replace(/\r\n?/g, '\n').split('\n');
  for (var p = 0; p < paragraphs.length; p++) {
    var chars = YuJianSvgChars(paragraphs[p].replace(/^\s+|\s+$/g, ''));
    if (!chars.length) continue;
    var line = '', width = 0;
    for (var i = 0; i < chars.length; i++) {
      var w = YuJianSvgCharWidth(chars[i]) * fontSize;
      if (line && width + w > maxWidth && noStart.indexOf(chars[i]) < 0) {
        lines.push(line);
        line = '';
        width = 0;
        if (chars[i] === ' ') continue;
      }
      line += chars[i];
      width += w;
    }
    if (line) lines.push(line);
  }
  if (maxLines && lines.length > maxLines) {
    lines = lines.slice(0, maxLines);
    lines[maxLines - 1] = YuJianSvgEllipsis(lines[maxLines - 1], fontSize, maxWidth, true);
  }
  return lines;
}

function YuJianSvgText(x, y, text, size, fill, extra) {
