  var y = 44;

  // 头部：头像 + 作者名 + 标签 + 月票信息
  svg += YuJianSvgAvatar(pad + 38, y + 38, 38, name, p.accent);
  var nameX = pad + 76 + 22, nameSize = 38;
  var nameText = YuJianSvgEllipsis(name, nameSize, inner - 76 - 22 - 150);
  svg += YuJianSvgLabel(p, nameX, y + 34, nameText, nameSize, p.fg, 'font-weight="bold"');
  var pillX = nameX + YuJianSvgTextWidth(nameText, nameSize) + 16;
  svg += '<rect x="' + pillX + '" y="' + (y + 2) + '" width="104" height="42" rx="21" fill="' + p.accent + '" fill-opacity="0.14"/>' +
    YuJianSvgText(pillX + 52, y + 32, '作家说', 26, p.accent, 'font-weight="bold" text-anchor="middle"');
  var meta = [];
  if (Number(ask.MonthTicketCount) > 0) meta.push('月票 ' + YuJianFormatCount(ask.MonthTicketCount));
  var rank = Number(ask.MonthTicketRank);
  if (rank > 0 && rank <= 500) meta.push('第 ' + rank + ' 名');
  svg += YuJianSvgLabel(p, nameX, y + 76, meta.length ? meta.join(' · ') : '本章作者留言', 28, p.muted);
  svg += YuJianSvgChevron(W - pad, y + 38, 30, p.muted);
  y += 76 + 56;

  // 正文
  var size = 40, lh = 66;
  var lines = YuJianSvgWrap(content, size, inner, 0);
  for (var i = 0; i < lines.length; i++) {
    svg += YuJianSvgLabel(p, pad, y + size, lines[i], size, p.fg);
    y += lh;
  }

  // 推荐书
  var rec = (authorSay.RecList || [])[0];
  if (rec && rec.BookName) {
    y += 14;
    var recName = '《' + String(rec.BookName) + '》';
    var recAuthor = rec.AuthorName ? ' · ' + String(rec.AuthorName) : '';
    var recAlpha = p.dark ? 0.12 : 0.08;
    var recSurface = YuJianEggMix(YuJianSvgNeutral, YuJianEggMix(YuJianSvgNeutral, p.bg, YuJianSvgCardAlpha(p)), recAlpha);
    svg += '<rect x="' + pad + '" y="' + y + '" width="' + inner + '" height="92" rx="22" fill="' + YuJianSvgNeutral + '" fill-opacity="' + recAlpha + '"/>';
    svg += '<g transform="translate(' + (pad + 28) + ',' + (y + 26) + ') scale(1.65)"><path d="M4 3.5A1.5 1.5 0 0 1 5.5 2H18v16H5.5A1.5 1.5 0 0 0 4 19.5v-16ZM4 19.5A1.5 1.5 0 0 0 5.5 21H18" fill="none" stroke="' + p.accent + '" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></g>';
    var recMax = inner - 96 - 28;
    var recNameText = YuJianSvgEllipsis('推荐' + recName, 32, recMax * 0.75);
    svg += YuJianSvgLabel(p, pad + 96, y + 57, recNameText, 32, p.fg, 'font-weight="bold"', recSurface);
    if (recAuthor) svg += YuJianSvgLabel(p, pad + 96 + YuJianSvgTextWidth(recNameText, 32) + 4, y + 57, YuJianSvgEllipsis(recAuthor, 30, recMax - YuJianSvgTextWidth(recNameText, 32) - 4), 30, p.muted, '', recSurface);
    y += 92;
  }

  // 求月票
  var expect = String(ask.AuthorExpectText || '').replace(/^\s+|\s+$/g, '');
  if (expect) {
    y += 30;
    svg += YuJianSvgDivider(pad, y, inner);
    y += 28;
    svg += '<g transform="translate(' + pad + ',' + (y + 4) + ') scale(1.5)"><path d="M3 7.5V6a1 1 0 0 1 1-1h16a1 1 0 0 1 1 1v1.5a2.5 2.5 0 0 0 0 5V14a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1v-1.5a2.5 2.5 0 0 0 0-5ZM9.5 5v10" fill="none" stroke="' + p.accent + '" stroke-width="1.8" stroke-linejoin="round"/></g>';
    var expectLines = YuJianSvgWrap(expect, 32, inner - 56, 2);
    for (var j = 0; j < expectLines.length; j++) {
      svg += YuJianSvgLabel(p, pad + 56, y + 30, expectLines[j], 32, p.accent);
      y += 50;
    }
    y -= 8;
  }
  y += 44;

  return YuJianSvgImage(String(bridge.base64Encode(YuJianSvgCard(W, y, p, svg)) || ''), {
    click: 'YuJianShowCmt(' + String(bookId) + ',' + String(chapterId) + ',-10)',
