function YuJianDrawChapterEnd(ctx, totalComments, bookId, chapterId, topReviews) {
  var bridge = YuJianBridge(ctx);
  if (!bridge || !bridge.base64Encode) return '';
  topReviews = (topReviews || []).filter(function(item) { return item && String(item.content || '').replace(/\s+/g, ''); }).slice(0, 3);
  var p = YuJianUiTheme(ctx).cur;
  var W = 1080, pad = 52, inner = W - pad * 2;
  var svg = '';
  var y = 44;

  // 头部
  svg += '<rect x="' + pad + '" y="' + (y + 6) + '" width="8" height="34" rx="4" fill="' + p.accent + '"/>';
  svg += YuJianSvgLabel(p, pad + 24, y + 36, '本章说', 40, p.fg, 'font-weight="bold"');
  svg += YuJianSvgLabel(p, pad + 24 + 128, y + 35, YuJianFormatCount(totalComments) + ' 条', 30, p.muted);
  svg += YuJianSvgLabel(p, W - pad - 30, y + 34, '查看全部', 30, p.accent, 'text-anchor="end"');
  svg += YuJianSvgChevron(W - pad, y + 24, 26, p.accent);
  y += 44 + 36;

  if (!topReviews.length) {
    svg += YuJianSvgLabel(p, pad, y + 34, '点击查看本章全部评论', 32, p.muted);
    y += 60;
  }

  var avatarR = 32, textX = pad + avatarR * 2 + 22, textW = W - pad - textX;
  for (var index = 0; index < topReviews.length; index++) {
    var review = topReviews[index];
    if (index > 0) {
      svg += YuJianSvgDivider(textX, y, W - pad - textX);
      y += 30;
    } else {
      y += 6;
    }
    var nickname = String(review.nickname || '书友');
    svg += YuJianSvgAvatar(pad + avatarR, y + avatarR, avatarR, nickname, YuJianSvgHueColor(nickname, p.dark));
    var likeText = YuJianFormatCount(review.likeCount);
    var likeW = YuJianSvgTextWidth(likeText, 28);
    svg += YuJianSvgLabel(p, W - pad, y + 30, likeText, 28, p.muted, 'text-anchor="end"');
    svg += YuJianSvgThumb(W - pad - likeW - 38, y + 4, 30, p.muted);
    svg += YuJianSvgLabel(p, textX, y + 30, YuJianSvgEllipsis(nickname, 30, textW - likeW - 60), 30, p.sub, 'font-weight="bold"');
    y += 44;
    var lines = YuJianSvgWrap(YuJianFormatEmoji(String(review.content || '')), 37, textW, 3);
    for (var i = 0; i < lines.length; i++) {
      svg += YuJianSvgLabel(p, textX, y + 38, lines[i], 37, p.fg);
