  return '(function(){try{localStorage.setItem("qd-theme",' + JSON.stringify(theme.isNight ? 'dark' : 'light') + ')}catch(e){}' +
    'var s=document.createElement("style");s.id="yujian-skin";s.textContent=' + JSON.stringify(YuJianCmtSkinCss(theme)) + ';' +
    '(document.head||document.documentElement).appendChild(s);' +
    'function trim(){var l=document.querySelectorAll(".zw span");for(var i=0;i<l.length;i++){var h=l[i].innerHTML,t=h.replace(/^(?:\\s|&nbsp;|\\u3000)+/,"");if(t!==h)l[i].innerHTML=t}}' +
    'document.addEventListener("DOMContentLoaded",function(){document.head.appendChild(s);trim();' +
    'new MutationObserver(trim).observe(document.body,{childList:true,subtree:true})})})();';
}

function YuJianShowCmt(arg1, arg2, arg3, arg4) {
  var ctx, bookId, chapterId, paragraphId;
  if (typeof arg1 === 'object' && arg1 !== null && (arg1.java || arg1.source || arg1.getVariable)) {
    ctx = arg1;
    bookId = arg2;
    chapterId = arg3;
    paragraphId = arg4;
  } else {
    ctx = (typeof this !== 'undefined' && this) || null;
    bookId = arg1;
    chapterId = arg2;
    paragraphId = arg3;
  }

  var bridge = YuJianBridge(ctx);
  var state = YuJianState(ctx);
  var token = YuJianCurrentToken(ctx, state);
  if (!token) token = YuJianCookie(ctx);
  if (!token) token = String(state.readerToken || '');
  var url = 'http://210.16.175.40:11451/comments?bookId=' + encodeURIComponent(String(bookId || '')) +
    '&chapterId=' + encodeURIComponent(String(chapterId || ''));
  if (paragraphId !== null && paragraphId !== undefined && String(paragraphId) !== '') {
    url += '&paragraphId=' + encodeURIComponent(String(paragraphId));
  }
  url += '&token=' + encodeURIComponent(String(token || ''));

  var halfConfig = JSON.stringify({
    state: 4,
    isHideable: true,
    heightPercentage: 0.85,
    expandedCornersRadius: 20,
    dismissOnTouchOutside: true,
    widthPercentage: 1.0,
    maxWidth: -1,
    skipCollapsed: true,
    hardwareAccelerated: true,
    webViewInitialScale: 100
  });
  var preloadJs = null;
  try { preloadJs = YuJianCmtPreloadJs(ctx); } catch (error) {}

  try {
    if (bridge && bridge.showBrowser) {
      bridge.showBrowser(url, null, preloadJs, halfConfig);
    } else if (bridge && bridge.startBrowserAwait) {
      bridge.startBrowserAwait(url, '评论');
    } else if (bridge && bridge.startBrowser) {
      bridge.startBrowser(url, '评论');
    } else if (bridge) {
      bridge.toast('当前阅读版本不支持内置浏览器');
    }
  } catch (error) {
    if (bridge && bridge.startBrowserAwait) {
      try { bridge.startBrowserAwait(url, '评论'); return; } catch (e1) {}
    }
    if (bridge && bridge.startBrowser) {
      try { bridge.startBrowser(url, '评论'); return; } catch (e2) {}
    }
    if (bridge) bridge.toast('无法打开评论：' + String((error && error.message) || error));
  }
}

// ===== 目录 =====
// 标记风格：A 图标点缀（默认）/ B 纯文字 / C 原版图标
var YuJianTocStyle = 'A';
var YuJianTocMarks = {
  A: { volume: '📖 ', egg: '🎁 ', note: '📢 ', cached: ' 🟢' },
  B: { volume: '', egg: '', note: '', cached: ' · 云端已存' },
  C: { volume: '', egg: '🌈 ', note: '', cached: ' 🍊' }
};

function YuJianTocMark(key) {
  var marks = YuJianTocMarks[YuJianTocStyle] || YuJianTocMarks.A;
  return marks[key] || '';
}

// 时间：今年显示「月-日 时:分」，往年只显示日期。不用「今天/昨天」，目录会缓存，相对时间会过时
function YuJianTocTime(timestamp) {
  timestamp = Number(timestamp || 0);
  if (timestamp > 0 && timestamp < 100000000000) timestamp *= 1000;
  if (!(timestamp > 0)) return '';
  var date = new Date(timestamp);
  if (isNaN(date.getTime())) return '';
  function two(value) { return (value < 10 ? '0' : '') + value; }
  var monthDay = two(date.getMonth() + 1) + '-' + two(date.getDate());
  if (date.getFullYear() === new Date().getFullYear()) {
    return monthDay + ' ' + two(date.getHours()) + ':' + two(date.getMinutes());
  }
  return date.getFullYear() + '-' + monthDay;
}

// 目录副标题：[共 N 个 ·] 字数 · 时间，服务器已缓存的章节在末尾加标记
function YuJianChapterInfo(result) {
  var item = result || {};
  var parts = [];
  var eggCount = Number(item.Egg || 0);
  if (eggCount > 1) parts.push('共 ' + eggCount + ' 个');
  var words = Number(item.W || 0);
  if (words > 0) parts.push(words + '字');
  var time = YuJianTocTime(item.T || item.DisplayTime);
  if (time) parts.push(time);
  var text = parts.join(' · ');
  if (Number(item.iscache || item.is_cached || item.isCache || 0) === 1) text += YuJianTocMark('cached');
  return text;
}

// 作者公告、请假条等单章：起点正文章节不会少于 500 字
function YuJianIsAuthorNote(item) {
  var words = Number(item.W || 0);
  return words > 0 && words < 500;
}

function YuJianEasterEggChapters(ctx, bookId) {
  var bridge = YuJianBridge(ctx);
  if (!bridge || !bookId) return [];
  try {
    var url = YuJianQDSign('v1/midpage/book/chapters', 'bookId=' + encodeURIComponent(String(bookId)), ctx);
    var raw = bridge.ajax(url);
    if (raw && typeof raw.body === 'function') raw = raw.body();
    var rows = (JSON.parse(String(raw || '{}')).Data || {}).Chapters || [];
    var result = [];
    for (var index = 0; index < rows.length; index++) {
      var row = rows[index];
      var pages = row.MidpageList || [];
      if (!row.ChapterId || !pages.length) continue;
      var names = [];
      var latest = 0;
      for (var pageIndex = 0; pageIndex < pages.length; pageIndex++) {
        var page = pages[pageIndex] || {};
        // 接口名字统一带「彩蛋章」前缀，标题前已有「彩蛋 ·」，去掉重复
        var name = String(page.MidpageName || '').replace(/^\s*彩蛋章?\s*[:：·]?\s*/, '').replace(/\s+/g, ' ').replace(/^\s+|\s+$/g, '');
        if (name && names.indexOf(name) < 0) names.push(name);
        latest = Math.max(latest, Number(page.UpdateTime || 0));
      }
      result.push({
        SourceChapterId: row.ChapterId,
        C: '彩' + row.ChapterId,
        N: YuJianTocMark('egg') + '彩蛋 · ' + (names.length ? names.join(' / ') : '本章彩蛋'),
        T: latest,
        V: 0,
        W: 0,
        Egg: pages.length
      });
    }
    return result;
  } catch (error) {
    return [];
  }
}

function YuJianTocList(ctx, result, baseUrl) {
  var root = YuJianParseResult(result);
  var data = root.Data || {};
  var chapters = (data.Chapters || []).slice();
  var bookId = YuJianBookIdFromToc(baseUrl);
  var state = YuJianState(ctx);

  // 分卷：按卷名连续分组（起点会把同一卷拆成免费、VIP 两段同名分卷，需要合并）
  var volumeNames = {};
  var volumes = data.Volumes || [];
  for (var v = 0; v < volumes.length; v++) {
    if (volumes[v] && volumes[v].VolumeCode !== undefined) {
      volumeNames[String(volumes[v].VolumeCode)] = String(volumes[v].VolumeName || '').replace(/^\s+|\s+$/g, '');
    }
  }
  var groups = [];
  for (var g = 0; g < chapters.length; g++) {
    var volumeName = volumeNames[String(chapters[g].Vc)] || '';
    var last = groups[groups.length - 1];
    if (!last || last.name !== volumeName) {
      last = { name: volumeName, count: 0 };
      groups.push(last);
    }
    last.count++;
    chapters[g].__group = groups.length - 1;
  }
  // 只有一卷或拿不到卷名时不加分卷标题
  var useVolumes = groups.length > 1 && groups.every(function(item) { return item.name; });

  if (state.easterEggs && bookId) {
    var eggs = YuJianEasterEggChapters(ctx, bookId);
    for (var eggIndex = 0; eggIndex < eggs.length; eggIndex++) {
      var egg = eggs[eggIndex];
      for (var chapterIndex = 0; chapterIndex < chapters.length; chapterIndex++) {
        if (String(chapters[chapterIndex].C) === String(egg.SourceChapterId)) {
          egg.__group = chapters[chapterIndex].__group;
          chapters.splice(chapterIndex + 1, 0, egg);
          break;
        }
      }
    }
  }

  var output = [];
  var currentGroup = -1;
  for (var index = 0; index < chapters.length; index++) {
    var chapter = chapters[index];
    if (useVolumes && chapter.__group !== currentGroup) {
      currentGroup = chapter.__group;
      var group = groups[currentGroup];
      // 卷名同时是卷页标题与阅读页顶栏标题；章数只算正文章节，不含插入的彩蛋
      var volumeTitle = YuJianTocMark('volume') + group.name + ' · ' + group.count + '章';
      output.push({
        name: volumeTitle,
        // 以卷名开头的链接，阅读不会去请求正文，update 就是卷页正文；
        // 留空时 MD3 把卷名上下左右居中成一页卷首，有任何正文都会退回普通章节排版
        url: volumeTitle + '#yujian-volume-' + currentGroup,
        volume: 1,
        vip: 0,
        update: ''
      });
    }
    var isEgg = String(chapter.C || chapter.CId || '').indexOf('彩') === 0;
    var name = String(chapter.N || '');
    if (!isEgg && YuJianIsAuthorNote(chapter)) name = YuJianTocMark('note') + name;
    output.push({
      name: name,
      url: isEgg ? YuJianEasterEggChapterUrl(baseUrl, chapter) : YuJianChapterUrl(baseUrl, chapter),
      volume: 0,
      vip: Number(chapter.V || 0) ? 1 : 0,
      update: YuJianChapterInfo(chapter),
      N: chapter.N,
      C: chapter.C,
      V: chapter.V,
      T: chapter.T
    });
  }
  return output;
}

// ===== 段评气泡 =====
// 气泡社区的样式可达上百 KB（如「竹韵」内嵌位图约 71KB），逐段内联后一章正文能涨到几十 MB，MD3 会内存溢出。
// 大模板只在正文里放一个带数字的小气泡占位，模板存进 cache，显示时由 imageDecode（YuJianBubbleDecode）换成真正的气泡。
var YuJianBubbleInlineMax = 1024;
// 占位编号的版本：MD3 按图片地址缓存解码结果，改了解码逻辑就递增，让旧版写下的占位图失效
var YuJianBubbleVersion = '2';
var YuJianBubbleFallback = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="5 14 45 36" width="180" height="144"><path d="M44 48 Q48 48 48 44 L48 20 Q48 16 44 16 L20 16 Q16 16 16 20 L16 24 S16 28 10 30 Q6 32 10 34 Q16 36 16 38 L16 44 Q16 48 20 48 Z" fill="none" stroke="#666666" stroke-width="0.7"/><text x="32" y="36.5" text-anchor="middle" font-family="system-ui,-apple-system,Arial,sans-serif" font-weight="600" font-size="11" fill="#666666">{n}</text></svg>';
// 多章会并发解析：备忘每次整体换成新对象，不会读到更新了一半的状态
var YuJianBubbleMemo = { encode: null, decode: null, failAt: 0 };

function YuJianCacheStore(ctx) {
  if (ctx && ctx.cache) return ctx.cache;
  if (typeof cache !== 'undefined') return cache;
  return null;
}

function YuJianBubbleFetch(ctx) {
  try {
    var options = YuJianRequestOptions(null, YuJianCurrentToken(ctx, YuJianState(ctx)));
    var svg = String(YuJianBridge(ctx).ajax(YuJianApiUrl('/bubbles/api/get-bubble', { keep_number: true }) + ',' + JSON.stringify(options)) || '');
    if (svg.indexOf('<svg') >= 0) return svg;
  } catch (error) {}
  return '';
}

function YuJianBubbleTemplate(ctx) {
  return YuJianBubbleFetch(ctx) || YuJianBubbleFallback;
}

function YuJianBubbleFill(template, display) {
  return String(template).replace(/\{n\}/g, display).replace(/\{N\}/g, display);
}

// 模板按内容哈希存进 cache（不过期）；同一模板只算一次哈希
function YuJianBubbleKey(ctx, template) {
  var memo = YuJianBubbleMemo.encode;
  if (memo && memo.template === template) return memo.key;
  var bridge = YuJianBridge(ctx);
  var seed = YuJianBubbleVersion + '|' + template;
  var key = String(bridge.md5Encode16 ? bridge.md5Encode16(seed) : String(bridge.md5Encode(seed)).slice(8, 24));
  var store = YuJianCacheStore(ctx);
  try {
    if (store && !store.get('yujian_bubble_' + key)) store.put('yujian_bubble_' + key, template);
  } catch (error) {}
  YuJianBubbleMemo.encode = { template: template, key: key };
  return key;
}

function YuJianBubbleSrc(ctx, count, bookId, chapterId, paragraphId, template) {
  var bridge = YuJianBridge(ctx);
  if (!bridge || !bridge.base64Encode) return '';
  template = String(template || YuJianBubbleTemplate(ctx) || '');
  if (!template) return '';
  var cnt = Number(count || 0);
  var display = cnt > 99 ? '99+' : String(cnt);
  var state = YuJianState(ctx);
  var options = {
    style: state.large ? 'TEXT' : 'text',
    type: 'img',
    click: 'YuJianShowCmt(this, ' + String(bookId) + ',' + String(chapterId) + ',' + String(paragraphId) + ')',
    marker: 'YuJianComment:' + bookId + ':' + chapterId + ':' + paragraphId
  };
  var svg;
  if (template.length > YuJianBubbleInlineMax) {
    options.yujianBubble = YuJianBubbleKey(ctx, template) + '|' + display;
    svg = YuJianBubbleFill(YuJianBubbleFallback, display);
  } else {
    svg = YuJianBubbleFill(template, display);
  }
  return 'data:image/svg+xml;base64,' + String(bridge.base64Encode(svg) || '') + ',' + JSON.stringify(options);
}

function YuJianCommentBubble(ctx, data, bookId, chapterId, paragraphId, template) {
  var src = YuJianBubbleSrc(ctx, (data || {}).count, bookId, chapterId, paragraphId, template);
  return src ? '<img src="' + src + '">' : '';
}

function YuJianTitleBubble(ctx, count, bookId, chapterId, template) {
  return YuJianBubbleSrc(ctx, count, bookId, chapterId, -1, template);
}

// 模板在 {n} 处切开并备忘，之后每张气泡只拼接数字，不再对整个模板跑正则
function YuJianBubbleParts(ctx, key) {
  var memo = YuJianBubbleMemo.decode;
  if (memo && memo.key === key) return memo.parts;
  var store = YuJianCacheStore(ctx);
  var template = '';
  try { template = String((store && store.get('yujian_bubble_' + key)) || ''); } catch (error) {}
  // cache 被清空时取一次当前气泡；失败后一分钟内不再重试，避免逐张图片请求
  if (template.indexOf('<svg') < 0 && Date.now() - YuJianBubbleMemo.failAt > 60000) {
    template = YuJianBubbleFetch(ctx);
    if (template) {
      try { if (store) store.put('yujian_bubble_' + key, template); } catch (error) {}
    } else {
      YuJianBubbleMemo.failAt = Date.now();
    }
  }
  if (template.indexOf('<svg') < 0) return null;
  var parts = template.split(/\{[nN]\}/);
  YuJianBubbleMemo.decode = { key: key, parts: parts };
  return parts;
}

// imageDecode 调用：把占位换成真正的气泡；任何失败都保留占位小气泡
// ctx 必须是 imageDecode 的 this：jsLib 函数按定义处的作用域找变量，看不到当次求值传入的 java、cache、source
function YuJianBubbleDecode(ctx, src, bytes) {
  try {
    var match = String(src || '').match(/"yujianBubble"\s*:\s*"([0-9a-fA-F]+)\|([^"]*)"/);
    if (!match) return bytes;
    var parts = YuJianBubbleParts(ctx, match[1]);
    if (!parts) return bytes;
    return YuJianBridge(ctx).strToBytes(parts.join(match[2]));
  } catch (error) {
    return bytes;
  }
}

// ===== 书籍详情：简介前加信息面板 =====
// MD3 详情页原样显示「图标 + 标签：值」的整行，书架和列表摘要会过滤掉这些行，只留简介正文。
// 行首必须是图标：以「作者：」「字数：」等字段名开头的行会被 MD3 当成重复信息删掉。
// 空行会被合并，段落之间用只含零宽空格的行隔开。
var YuJianIntroGap = '\u200B';

function YuJianIntroWords(words) {
  words = Number(words || 0);
  if (!(words > 0)) return '';
  return words >= 10000 ? (words / 10000).toFixed(2) + '万字' : words + '字';
}

function YuJianIntroTime(timestamp) {
  timestamp = Number(timestamp || 0);
  if (!(timestamp > 0)) return '';
  var date = new Date(timestamp);
  if (isNaN(date.getTime())) return '';
  function two(value) { return (value < 10 ? '0' : '') + value; }
  return date.getFullYear() + '-' + two(date.getMonth() + 1) + '-' + two(date.getDate()) + ' ' + two(date.getHours()) + ':' + two(date.getMinutes());
}

function YuJianIntroTrim(text) {
  return String(text === undefined || text === null ? '' : text).replace(/^\s+|\s+$/g, '');
}

// 荣耀星级只留最高一档，其余按接口顺序，放不下的用「等 N 项」收尾
function YuJianIntroHonors(list, total) {
  var stars = ['', '一', '二', '三', '四', '五'];
  var star = 0, names = [];
  for (var i = 0; i < (list || []).length; i++) {
    var name = YuJianIntroTrim((list[i] || {}).Honors);
    var match = name.match(/^荣耀([一二三四五])星$/);
    if (match) {
      star = Math.max(star, stars.indexOf(match[1]));
    } else if (name && names.indexOf(name) < 0) {
      names.push(name);
    }
  }
  if (star) names.unshift('荣耀' + stars[star] + '星');
  var text = '', shown = 0;
  for (var j = 0; j < names.length; j++) {
    if (shown && (text + '、' + names[j]).length > 24) break;
    text += (shown ? '、' : '') + names[j];
    shown++;
  }
  total = Math.max(Number(total || 0), names.length);
  return text && total > shown ? text + ' 等 ' + total + ' 项' : text;
}

// 服务器目录：登录后章节才带缓存标记，没有标记时返回 null，不显示这一行
function YuJianIntroCache(raw) {
  var chapters = (YuJianParseResult(raw).Data || {}).Chapters || [];
  var known = false, cached = 0;
  for (var i = 0; i < chapters.length; i++) {
    var item = chapters[i] || {};
    var flag = item.iscache !== undefined ? item.iscache : item.is_cached !== undefined ? item.is_cached : item.isCache;
    if (flag === undefined) continue;
    known = true;
    if (Number(flag) === 1) cached++;
  }
  return known ? { cached: cached, total: chapters.length } : null;
}

function YuJianIntroResponses(ctx, urls) {
  var bridge = YuJianBridge(ctx);
  var bodies = [];
  if (!bridge || !urls.length) return bodies;
  try {
    var res = bridge.ajaxAll ? bridge.ajaxAll(urls) : urls.map(function(url) { return bridge.ajax(url); });
    for (var i = 0; i < urls.length; i++) {
      var item = res[i];
      bodies.push(String((item && typeof item.body === 'function' ? item.body() : item) || ''));
    }
  } catch (error) {}
  return bodies;
}

function YuJianRelatedTagUrl(book, bridge) {
  var data = {};
  try { data = (YuJianParseResult(bridge.ajax(String(book.bookUrl))) || {}).Data || {}; } catch (error) {}
  var tags = data.BookUgcTag || [];
  for (var i = 0; i < tags.length; i++) {
    var tag = tags[i] || {};
    if (Number(tag.Type) === 1 && Number(tag.TagId) > 0 && tag.TagName) {
      return YuJianSearchUrl(String(tag.TagName), 1);
    }
  }
  return '';
}

function YuJianBookIntro(ctx, result) {
  var data = (YuJianParseResult(result) || {}).Data || {};
  var bookId = String(data.BookId || '');
  var authorInfo = data.AuthorInfo || {};

  // 额外请求服务器目录，只在登录后统计已缓存章节
  var urls = [];
  var token = '';
  try { token = YuJianCurrentToken(ctx, YuJianState(ctx)); } catch (error) {}
  if (bookId && token) {
    urls.push(YuJianApiUrl('/books/' + encodeURIComponent(bookId) + '/chapters') + ',' + JSON.stringify(YuJianRequestOptions(null, token)));
  }
  var bodies = YuJianIntroResponses(ctx, urls);
  var cacheInfo = null;
  if (bodies.length) {
    try { cacheInfo = YuJianIntroCache(bodies[0]); } catch (error) {}
  }

  var lines = [];
  function add(icon, label, value) {
    value = YuJianIntroTrim(value);
    if (value) lines.push(icon + ' ' + label + '：' + value);
  }
  add('🆔', '书籍ID', bookId);
  if (cacheInfo) add('🔐', '缓存', '服务器已缓存 ' + cacheInfo.cached + ' / ' + cacheInfo.total + ' 章');
  var authorMeta = [];
  if (authorInfo.AuthorLevel) authorMeta.push(authorInfo.AuthorLevel);
  if (Number(authorInfo.BookCount) > 0) authorMeta.push(authorInfo.BookCount + ' 部作品');
  add('✍️', '作者', YuJianIntroTrim(data.Author || authorInfo.AuthorName) + (authorMeta.length ? '（' + authorMeta.join(' · ') + '）' : ''));
  add('✨', '状态', [data.BookStatus, YuJianIntroTrim(data.JoinTimeCopyRight)].filter(Boolean).join(' · '));
  add('📝', '字数', YuJianIntroWords(data.WordsCnt));
  add('📑', '分类', [data.CategoryName, data.SubCategoryName].filter(Boolean).join(' / '));
  var vipTime = Number(data.LastVipChapterUpdateTime || 0), freeTime = Number(data.LastChapterUpdateTime || 0);
  var latestIsVip = vipTime >= freeTime && data.LastVipUpdateChapterName;
  add('📄', '最新章节', latestIsVip ? data.LastVipUpdateChapterName : (data.LastUpdateChapterName || data.LastVipUpdateChapterName));
  add('⏰', '更新时间', YuJianIntroTime(Math.max(vipTime, freeTime)));
  add('🏆', '荣誉', YuJianIntroHonors(data.BookHonor, data.HonorTotalCount));
  if (Number(data.MonthTicketCount) > 0) add('🎫', '月票', YuJianFormatCount(data.MonthTicketCount));
  if (Number(data.BssRecomTotal) > 0) add('🎟️', '推荐', YuJianFormatCount(data.BssRecomTotal));
  if (Number(data.TotalFansCount) > 0) add('❤️', '粉丝', YuJianFormatCount(data.TotalFansCount));

  var description = String(data.Description || '').split(/\r?\n/).map(YuJianIntroTrim).filter(Boolean);
  if (description.length) lines.push(YuJianIntroGap, '📖 简介：');
  lines = lines.concat(description);

  var roles = data.RoleList || [];
  if (roles.length) {
    var roleTotal = Number(data.TotalRoleCount || 0);
    lines.push(YuJianIntroGap, '🎭 角色' + (roleTotal > roles.length ? '（共 ' + roleTotal + ' 位）' : '') + '：');
    for (var r = 0; r < roles.length; r++) {
      var role = roles[r] || {};
      var roleName = YuJianIntroTrim(role.RoleName);
      if (!roleName) continue;
      var roleDesc = YuJianIntroTrim(role.RoleDesc).replace(/\s*[\r\n]+\s*/g, ' ');
      lines.push('- ' + roleName + (role.Position ? '（' + YuJianIntroTrim(role.Position) + '）' : '') + (roleDesc ? '：' + roleDesc : ''));
    }
  }

  return lines.join('\n');
}

// MD3 beta.50 discovery: normalize search and existing related-book feeds.
function YuJianDiscoveryUrl(keyword, page, authorOnly) {
  var request = YuJianSearchUrl(String(keyword || ''), Number(page) || 1);
  if (!authorOnly) return request;
  var comma = request.indexOf(',');
  return request.substring(0, comma) + '?yujian_author=' +
    encodeURIComponent(String(keyword)) + request.substring(comma);
}

function YuJianExploreBooks(raw, currentUrl) {
  var payload = JSON.parse(String(raw));
  if (!payload || typeof payload !== 'object') {
    throw new Error('发现接口返回了无效数据，请稍后重试');
  }
  var data = payload.Data || {};
  var uri = String(currentUrl || '');
  var mode = (uri.match(/[?&]related=(author|same)(?:[&#]|$)/) || [])[1];
  var authorOnly = (uri.match(/[?&]yujian_author=([^&#]*)/) || [])[1];
  if (authorOnly) authorOnly = decodeURIComponent(authorOnly);
  var list;
  if (mode === 'author') {
    list = data.AuthorBookList || [];
  } else if (mode === 'same') {
    list = data.SameRecommend || [];
  } else if (Array.isArray(payload.books)) {
    list = payload.books;
  } else {
    throw new Error('发现接口暂不可用，请刷新后重试');
  }
  var seen = {};
  var books = [];
  for (var i = 0; i < list.length; i++) {
    var item = list[i] || {};
    var id = String(item.BookId || item.book_id || '');
    var name = String(item.BookName || item.name || '').trim();
    // Search sometimes includes audio/advertising items with book_id=0.
    if (!/^\d+$/.test(id) || Number(id) <= 0 || !name || seen[id]) continue;
    seen[id] = true;
    var author = item.AuthorName || item.author || '';
    if (authorOnly && String(author).trim() !== authorOnly) continue;
    if (!author && mode === 'author') {
      author = data.AuthorName || data.Author || '';
      if (typeof author !== 'string') author = '';
    }
    var category = item.CategoryName || item.category || '';
    var status = item.BookStatus || item.status || '';
    books.push({
      BookId: id,
      BookName: name,
      AuthorName: String(author),
      WordsCount: item.WordsCount || item.words || item.WordsCnt || 0,
      Intro: String(item.Description || item.intro || ''),
      Kind: [category, status].filter(function(value) { return !!value; }).join(','),
      LastChapter: String(item.LastChapterName || item.last_chapter || '')
    });
  }
  return books;
}

