(function() {
  var text = String(src || '');
  if (text.indexOf('"yujianBubble"') >= 0) {
    try { return YuJianBubbleDecode(this, text, result); } catch (error) { return result; }
  }
  var sliceMatch = text.match(/[?&]yujian_slice=(\d+)/);
  if (!sliceMatch) return result;

  var heightMatch = text.match(/[?&]yujian_slice_height=(\d+)/);
  var sliceHeight = Math.max(1, Number(heightMatch ? heightMatch[1] : 1280));
  var sliceIndex = Math.max(0, Number(sliceMatch[1]));

  var BitmapFactory = Packages.android.graphics.BitmapFactory;
  var Bitmap = Packages.android.graphics.Bitmap;
  var ByteArrayOutputStream = Packages.java.io.ByteArrayOutputStream;
  var bitmap = BitmapFactory.decodeByteArray(result, 0, result.length);
  if (!bitmap) return result;

  var top = sliceIndex * sliceHeight;
  if (top < 0 || top >= bitmap.getHeight()) return result;

  var cropHeight = Math.min(sliceHeight, bitmap.getHeight() - top);
  if (cropHeight <= 0) return result;

  var slice = Bitmap.createBitmap(bitmap, 0, top, bitmap.getWidth(), cropHeight);
  var output = new ByteArrayOutputStream();
  slice.compress(Bitmap.CompressFormat.JPEG, 92, output);
  return output.toByteArray();
})()

