exploreUrl:
@js:
/* 发现页：原来只有一行请求，服务器 /explore/kinds 失败或返回空时
   整个发现页变空白、所有按钮失效。这里加：
     ① 失败重试一次（网络抖动很常见）
     ② 仍失败则给提示项，不再空白
   对照企点（其 exploreUrl 有 try/catch 与 18 个榜单兜底）。 */
function _exFail(msg) {
  return JSON.stringify([
    {"title": "\u53d1\u73b0\u9875\u52a0\u8f7d\u5931\u8d25", "url": "", "style": {"layout_flexGrow": 1, "layout_flexBasisPercent": 1}},
    {"title": msg, "url": "", "style": {"layout_flexGrow": 1, "layout_flexBasisPercent": 1}},
    {"title": "\u2192 \u70b9\u51fb\u91cd\u8bd5", "url": "javascript:", "style": {"layout_flexGrow": 1, "layout_flexBasisPercent": 1}}
  ]);
}
var O = '';
try { O = qdApiBase.call(this); } catch (e0) { O = String(this.source.bookSourceUrl || ''); }
var ex = String(source.get('fqm_explore') || 'qidian');
if (ex == 'qidian') { try { qdEnsureToken.call(this); } catch (e) {} }
var _u = O + '/explore/kinds?min=1&explore=' + ex;
var _r = '';
try { _r = java.ajax(_u); } catch (e1) { _r = ''; }
/* 重试一次 */
if (!_r || String(_r).charAt(0) === '<' || String(_r).length < 10) {
  try { _r = java.ajax(_u); } catch (e2) { _r = ''; }
}
if (!_r || String(_r).length < 10) { _exFail('\u670d\u52a1\u5668\u65e0\u54cd\u5e94'); }
else if (String(_r).charAt(0) === '<') { _exFail('\u670d\u52a1\u5668\u8fd4\u56de\u5f02\u5e38'); }
else {
  try {
    var _j = JSON.parse(_r);
    if (!_j || (Object.prototype.toString.call(_j) === '[object Array]' && !_j.length)) {
      _exFail('\u670d\u52a1\u5668\u8fd4\u56de\u7a7a');
    } else { _r; }
  } catch (e3) { _exFail('\u6570\u636e\u89e3\u6790\u5931\u8d25'); }
}

