var qdTokApplied = 0;
function qdDeviceId(){
  var src=this.source, d='';
  try{ d=String(src.get('qd_dev')||''); }catch(e){}
  if(!/^[a-f0-9]{32}$/.test(d)){
    d=''; for(var i=0;i<32;i++){ d+='0123456789abcdef'.charAt(Math.floor(Math.random()*16)); }
    try{ src.put('qd_dev',d); }catch(e){}
  }
  return d;
}
function qdTokenVal(){
  var src=this.source, t='';
  try{ t=String(src.get('qd_at')||''); }catch(e){}
  return t;
}
function qdKillSess(base){
  var ck='';
  try{ ck=String(this.cookie.getCookie(base)||''); }catch(e){}
  if(ck.indexOf('admin_session')<0) return;
  var keep=[], parts=String(ck).split(';');
  for(var i=0;i<parts.length;i++){
    var p=String(parts[i]).replace(/^\s+|\s+$/g,'');
    if(p && p.indexOf('admin_session=')!==0) keep.push(p);
  }
  try{ this.cookie.removeCookie(base); }catch(e){}
  if(keep.length){ try{ this.cookie.setCookie(base, keep.join('; ')); }catch(e){} }
}
function qdKillWebSessions(){
  var bases={};
  try{ bases[qdAuthBase.call(this)]=1; }catch(e){}
  try{ var cb=String(this.source.get('qd_base')||''); if(cb) bases[cb]=1; }catch(e){}
  try{ bases[String(this.source.bookSourceUrl)]=1; }catch(e){}
  for(var b in bases){ try{ qdKillSess.call(this,b); }catch(e){} }
}
function qdApplyToken(force){
  var now=Date.now();
  if(!force && qdTokApplied && (now-qdTokApplied)<60000) return '';
  var tok=qdTokenVal.call(this);
  if(!tok) return '';
  try{
    this.source.putLoginHeader(JSON.stringify({
      "X-Auth-Token": tok,
      "X-Device-Id": qdDeviceId.call(this),
      "Cookie": "at="+tok
    }));
    qdTokApplied=now;
    var _v='';
    try{ _v=String(this.source.get('qd_tok_valid')||''); }catch(e){}
    if(_v=='1'){ qdKillWebSessions.call(this); }
  }catch(e){}
  return tok;
}
function qdMirrorToken(base){
  try{ var t=qdTokenVal.call(this); if(t&&base) this.cookie.setCookie(base,'at='+t); }catch(e){}
}
function isFq(u) { u = String(u || ''); return /source=fanqie/.test(u) || /\/fanqie\//.test(u); }

function fqPick(u, re, d) { var m = String(u || '').match(re); return m ? m[1] : d; }

function jparse(r) { try { return JSON.parse(r) || {}; } catch (e) { return {}; } }
function fqEnsureEnv(result) {
    var java = this.java, self = this;
    function checkEnv() {
        try { new Packages.io.legato.kazusa.utils.TimeoutCancellationException(''); return true; }
        catch (e) { return (typeof self.source.loginUi == 'function') ? false : true; }
    }
    try { java.put('bbpd', checkEnv() ? '改版' : '原版'); } catch (e) { java.put('bbpd', '原版'); }
    var devType = '安卓';
