            name: b.book_name || b.title || '', author: b.author || '',
            cover: b.thumb_url || b.cover_url || b.audio_thumb_uri || '', intro: b.abstract || '',
            kind: [b.category, b.sub_title].filter(Boolean).join('\n'), last: b.last_chapter_title || '', words: b.word_number || '',
