/* ===== 通用书籍提取 =====
   不再猜层级：递归找第一个「像书籍数组」的数组，再按别名归一化字段名。
   参考企点 ruleExplore 里 $.bid||$.BookId 的兼容写法，但覆盖更全。 */
var QD_BK_NAME = ['bName', 'BookName', 'bookName', 'name', 'title', 'book_name', 'bookname', 'BookTitle'];
var QD_BK_ID   = ['bid', 'BookId', 'bookId', 'book_id', 'id', 'bId'];
