/* 递归找第一个书籍数组 */
function qdFindBooks(node, depth) {
  if (!node || typeof node !== 'object' || depth > 6) return null;
  if (Object.prototype.toString.call(node) === '[object Array]') {
    var hit = 0;
    for (var i = 0; i < node.length && i < 5; i++) if (qdLooksBook(node[i])) hit++;
