  var prefer = ['records', 'list', 'bookList', 'books', 'book_info', 'BookInfo',
    'item_list', 'item_data_list', 'cell_data', 'data', 'Data', 'items', 'result'];
  for (var p = 0; p < prefer.length; p++) {
    var v = node[prefer[p]];
    if (v && typeof v === 'object') {
