  var sample = arr[0];
  if (!sample || typeof sample !== 'object') return 0;
  var s = 0;
  if (sample.segmentId != null || sample.segmentID != null || sample.paragraphId != null) s += 10;
  if (sample.textCount != null || sample.reviewNum != null || sample.reviewCount != null) s += 5;
  if (sample.content != null || sample.Content != null) s += 10;
