}

/* 每条评论最多几张图：图片解码吃内存，单条刷太多会撑爆低内存设备 */
var QD_MAX_IMG_ONE = 3;
var QD_IMG_SEQ = 0;
function qdImgReset() { QD_IMG_SEQ = 0; }
function qdImgAllow() {
  if (QD_IMG_SEQ >= QD_MAX_IMG_ONE) return false;
  QD_IMG_SEQ++;
  return true;
}

function qdRenderFull(it) {
  if (!it || typeof it !== 'object') return '';
  var t = qdRenderTextEx(it.content || it.Content || '');
  var imgs = qdItemImages(it);
  for (var i = 0; i < imgs.length; i++) {
    /* 内容里已经有这张图就不重复加 */
    if (t.indexOf(String(imgs[i])) >= 0) continue;
    t += qdImgTag(imgs[i]);
  }
  return t;
}

/* ===== 回复分组：主楼 + 内嵌回复（保留层级）===== */
function qdGroup(list) {
  var out = [];
  if (!list || !list.length) return out;
  for (var i = 0; i < list.length; i++) {
    var it = list[i];
    if (!it || typeof it !== 'object') continue;
    if (it.__isReply) continue;   /* 已被展开的回复跳过，由父级带出 */
    var g = { main: it, replies: [] };
    for (var r = 0; r < QD_REPLY_KEYS.length; r++) {
      var sub = it[QD_REPLY_KEYS[r]];
      if (sub && qdIsArr(sub) && sub.length) {
        for (var k = 0; k < sub.length; k++) {
          if (sub[k] && typeof sub[k] === 'object') g.replies.push(sub[k]);
        }
        break;
      }
    }
    out.push(g);
  }
  return out;
}

/* ===== 配音识别 ===== */
var QD_VOICE_KEYS = ['voiceUrl', 'VoiceUrl', 'audioUrl', 'AudioUrl', 'voice', 'Voice',
  'audio', 'Audio', 'soundUrl', 'SoundUrl', 'sound', 'Sound', 'voiceList', 'VoiceList',
  'audioList', 'AudioList', 'recordUrl', 'RecordUrl', 'mediaUrl', 'MediaUrl',
  'voicePath', 'VoicePath', 'attachment', 'Attachment', 'media', 'Media'];

function qdIsAudio(u) {
  var s = String(u || '');
  if (!s) return false;
  if (/\.(mp3|m4a|wav|aac|ogg|flac|amr)(\?|$)/i.test(s)) return true;
  return /(voice|audio|sound|record)/i.test(s) && /^https?:\/\//i.test(s);
}

function qdNormUrl(u) {
  var s = String(u || '');
  if (/^\/\//.test(s)) return 'https:' + s;
  if (/^\//.test(s)) return 'https://m.qidian.com' + s;
  return s;
}

function qdAnyVoice(it) {
  if (!it) return '';
  var i, v, u;
  for (i = 0; i < QD_VOICE_KEYS.length; i++) {
    v = it[QD_VOICE_KEYS[i]];
    if (!v) continue;
    if (typeof v === 'string' && qdIsAudio(v)) return qdNormUrl(v);
    if (typeof v === 'object' && !qdIsArr(v)) {
      u = v.url || v.src || v.path || v.voiceUrl || v.audioUrl;
      if (u && qdIsAudio(u)) return qdNormUrl(u);
    }
    if (qdIsArr(v)) {
      for (var j = 0; j < v.length; j++) {
        var o = v[j];
        if (typeof o === 'string' && qdIsAudio(o)) return qdNormUrl(o);
        if (o && typeof o === 'object') {
          var u2 = o.url || o.src || o.voiceUrl || o.audioUrl;
          if (u2 && qdIsAudio(u2)) return qdNormUrl(u2);
        }
      }
    }
  }
  /* 深度扫描兜底 */
  var out = [];
  try {
    (function walk(o, d) {
      if (!o || d > 4 || out.length) return;
      if (typeof o === 'string') {
        if (qdIsAudio(o)) out.push(qdNormUrl(o));
        return;
      }
      if (typeof o !== 'object') return;
      var arr = qdIsArr(o) ? o : null;
      if (arr) { for (var k = 0; k < arr.length && !out.length; k++) walk(arr[k], d + 1); return; }
      for (var key in o) {
        if (!o.hasOwnProperty(key)) continue;
        if (/^(avatar|userimg|headimg|portrait|face|photo|pic|cover)$/i.test(key)) continue;
        try { walk(o[key], d + 1); } catch (e) {}
        if (out.length) break;
      }
    })(it, 0);
  } catch (e) {}
  return out.length ? out[0] : '';
}

/* ===== 段评日夜：跟随阅读器（参考阅读界面右上角的弯月按钮）=====
   存储 qd_night：'' = 跟随 | '0' = 强制日间 | '1' = 强制夜间
   跟随优先探测阅读器自身的夜间态；探测不到才回落系统深色模式。 */

/* 探测阅读器是否处于夜间。legado 各版本暴露的键名不一，逐个安全试。 */
function qdReaderNight(ctx) {
  try {
    var java = ctx && ctx.java;
    if (!java || !java.get) return null;
    var keys = ['nightTheme', 'isNightTheme', 'isNight', 'night', 'nightMode',
      'theme', 'themeMode', 'darkMode', 'isDark', 'readerTheme', 'readTheme',
      'isNightMode', 'night_mode', 'dark'];
    for (var i = 0; i < keys.length; i++) {
      var v = '';
      try { v = String(java.get(keys[i]) || ''); } catch (e) { continue; }
      if (!v) continue;
      var lv = v.toLowerCase();
      if (v === '1' || lv === 'true' || lv === 'night' || lv === 'dark' || lv === '2') return true;
      if (v === '0' || lv === 'false' || lv === 'day' || lv === 'light') return false;
    }
  } catch (e) {}
  return null;
}

/* 返回 'day' | 'night' | 'auto'（auto = 交给 CSS media 跟随系统） */
function qdNightNow(ctx) {
  var v = '';
  try { v = String(ctx.source.get('qd_night') || ''); } catch (e) {}
  if (v === '0') return 'day';
  if (v === '1') return 'night';
  var n = qdReaderNight(ctx);
  if (n === true) return 'night';
  if (n === false) return 'day';
  return 'auto';
}

/* 空态面板（暂无段评 / 加载失败）：日间色为底，深色按主题切换 */
function qdEmptyThemeCss(ctx, dbg, dfg, lbg, lfg) {
  var t = qdNightNow(ctx);
  if (t === 'night') return 'background:' + dbg + ';color:' + dfg;
  if (t === 'day') return 'background:' + lbg + ';color:' + lfg;
  return 'background:' + lbg + ';color:' + lfg +
    '}@media (prefers-color-scheme: dark){body{background:' + dbg + ';color:' + dfg;
}

/* 面板内切换后写回 source 变量（下次打开沿用）。
