/* 单条主楼 */
function qdMainHtml(it, actualReply) {
  var name = String(it.userName || it.nickName || it.UserName || it.nickname || "\u533f\u540d");
  var meta = [];
  var floor = qdFloorOf(it);
  if (floor) meta.push("\u7b2c" + floor + "\u697c");
  var tm = qdTimeOf(it);
  if (tm) meta.push(tm);
  var ip = String(it.ipAddress || it.ipLocation || it.location || "").replace(/^IP(?:\u5c5e\u5730|\u5f52\u5c5e\u5730)\s*[:：]?\s*/i, "");
  if (ip) meta.push(ip);
  var like = Number(it.likeCount || it.agreeAmount || it.AgreeAmount || 0);
  /* 接口常不返回计数字段（或返回 0），但回复数组里确实有内容。
     以实际拿到的回复数为准，字段值只作兜底（取较大者）。 */
  var reply = Math.max(Number(actualReply || 0), Number(it.replyCount || it.replyNum || 0));
  var god = Number(it.isFine || it.isHot || 0) === 1;
  var lvl = it.userLevel || it.vipLevel || it.readerLevel;

  var voice = "";
  try { voice = qdAnyVoice(it); } catch (eV) {}
  var contentHtml = "";
  try { contentHtml = qdRenderFull(it); } catch (eC) { contentHtml = qdEscHtml(String(it.content || it.Content || "")); }
  var hasImg = /<img[\s>]/i.test(contentHtml);
  var hasVoice = !!voice;

  /* 超长正文折叠：几千字的评论会占满整屏，默认收起到 6 行。
     用纯 CSS（checkbox + 兄弟选择器），不破坏内容里的 HTML/图片。 */
  var tooLong = false;
  var cbox = "";
  try {
    var plain = String(contentHtml).replace(/<[^>]*>/g, "");
    if (plain.length > QD_LONG_TEXT) {
      tooLong = true;
      var lid = "lt-" + (QD_LT_SEQ++);
      cbox = '<input class="tabin" type="checkbox" id="' + lid + '">';
      /* 展开按钮放正文后，靠 CSS 在展开状态下隐藏 */
      var moreBtn = '<label class="ltmore" for="' + lid + '">\u5c55\u5f00\u5168\u6587</label>';
      contentHtml = '<div class="ltbox" id="' + lid + '-box">' +
        '<div class="ltin">' + contentHtml + "</div></div>" + moreBtn;
      /* 用 id 定位：CSS 里靠 :checked + 相邻兄弟 */
      contentHtml = cbox + '<div class="ltwrap">' + contentHtml + "</div>";
    }
  } catch (eL) {}

  var html = '<div class="m">' + qdAvatarHtml(it, name) +
    '<span class="n">' + qdEscHtml(name) + "</span>" +
    (lvl ? '<span class="lv">Lv' + qdEscHtml(String(lvl)) + "</span>" : "") +
    (god ? '<span class="god">\u795e\u8bc4</span>' : "") +
    (meta.length ? '<span class="fl">' + qdEscHtml(meta.join(" \u00b7 ")) + "</span>" : "") +
    "</div>" +
    (contentHtml ? '<div class="b">' + contentHtml + "</div>" : "") +
    (voice ? '<audio class="au" controls preload="none" src="' + qdEscHtml(voice) + '"></audio>' : "") +
    '<div class="f"><span>\uD83D\uDC4D ' + like + "</span><span>\uD83D\uDCAC " +
    (reply || (it.__replyCount || 0)) + "</span></div>";

  return { html: html, hasImg: hasImg, hasVoice: hasVoice };
}

