function qdShellOnly(html) {
  var t = String(html || '');
  if (!t || t.indexOf('<html') < 0) return true;
  if (/还没有段评|还没有评论|暂无评论|暂无段评|评论加载失败/.test(t)) return true;
  /* 没有任何评论痕迹（昵称/内容/楼层/点赞）就当外壳 */
  var marks = ['class="cmt', 'class=\'cmt', 'nickname', 'userName', 'comment-item',
    'review-item', 'floor', 'likeCount', '段评'];
  for (var i = 0; i < marks.length; i++) {
    if (t.indexOf(marks[i]) >= 0) return false;
  }
  return true;
}

/* 防重复点击：同一段短时间内重复点，直接复用上次的面板，不再发请求。
   键里带请求指纹，避免把「加载失败」的空态也当成有效结果复用。 */
var QD_CLICK_GAP = 3000;  /* 3 秒内复用上次面板（用户关掉再点，快速显示） */
var QD_DEBOUNCE = 1200;   /* 1.2 秒内的重复点击直接忽略：面板还开着，再弹没意义 */

function qdClickGuardKey(bid, cid, para) {
  return 'qdclk-' + bid + '-' + cid + '-' + para;
}

function qdClickGuardGet(ctx, bid, cid, para) {
  try {
    var raw = String(ctx.cache.getFromMemory(qdClickGuardKey(bid, cid, para)) || '');
    if (!raw) return '';
    var i = raw.indexOf('|');
    if (i < 0) return '';
    var ts = Number(raw.substring(0, i));
    if (!ts || (Date.now() - ts) > QD_CLICK_GAP) return '';
    return raw.substring(i + 1);
  } catch (e) { return ''; }
}

/* 进行中锁：与防抖不同——防抖管"面板重复弹"，这个管"请求重复发"。
   进入即标记、结束才释放；异常残留由 60 秒超时兜底。 */
function qdBusyKey(bid, cid, para) {
  return 'qdbusy-' + bid + '-' + cid + '-' + para;
}
function qdBusyGet(ctx, bid, cid, para) {
  try {
    var ts = Number(ctx.cache.getFromMemory(qdBusyKey(bid, cid, para)) || 0);
    if (!ts) return false;
    if (Date.now() - ts > 60000) return false;   /* 超时视为残留，不再算忙碌 */
    return true;
  } catch (e) { return false; }
}
function qdBusySet(ctx, bid, cid, para) {
  try { ctx.cache.putMemory(qdBusyKey(bid, cid, para), String(Date.now())); } catch (e) {}
}
function qdBusyClear(ctx, bid, cid, para) {
  try { ctx.cache.putMemory(qdBusyKey(bid, cid, para), ''); } catch (e) {}
}

/* 距上次弹出面板过了多少毫秒（-1 表示没有记录） */
function qdClickAge(ctx, bid, cid, para) {
  try {
    var raw = String(ctx.cache.getFromMemory(qdClickGuardKey(bid, cid, para)) || '');
    if (!raw) return -1;
    var i = raw.indexOf('|');
    if (i < 0) return -1;
    var ts = Number(raw.substring(0, i));
    return ts ? (Date.now() - ts) : -1;
  } catch (e) { return -1; }
}

function qdClickGuardPut(ctx, bid, cid, para, html) {
  try {
    ctx.cache.putMemory(qdClickGuardKey(bid, cid, para),
      String(Date.now()) + '|' + String(html));
  } catch (e) {}
}

function qdOpenCmtFb(url, bid, cid, para, title) {
  var java = this.java;

  /* 0) 重复点击保护：3 秒内再点同一段，直接复用上次面板 */
  var _guard = qdClickGuardGet(this, bid, cid, para);
  if (_guard) {
    /* 防抖：距上次弹出不到 1.2 秒 → 面板大概率还开着，直接忽略。
       之前这里仍会 showBrowser，导致快速连点弹出两个面板。 */
    var _age = qdClickAge(this, bid, cid, para);
    if (_age >= 0 && _age < QD_DEBOUNCE) return;
    /* 超过防抖时间（用户关掉面板又点）→ 复用 HTML 立即显示，不发请求 */
    var _cfg0 = null;
    try { _cfg0 = qdHalfCfg.call(this); } catch (eG) {}
    if (_cfg0) java.showBrowser(url, _guard, qdPreJs(), _cfg0);
    else java.showBrowser(url, _guard, qdPreJs());
    return;
  }

  /* 1) 气泡带的是「第几段」，先换成起点要的真实 segmentId。
        之前直接用顺序号去问起点，取不到就退回章评(-1)，
        于是每个段落都显示同一份章评 —— 这就是"段评重复"的原因。 */
  /* 进行中锁：正在取评论时重复进入 → 直接返回，避免真发两次请求 */
  if (qdBusyGet(this, bid, cid, para)) return;
  qdBusySet(this, bid, cid, para);
  try {
  var segUsed = qdSegReal(this, bid, cid, para);
  var _wantN = 0;
  try { _wantN = qdWantGet(this, bid, cid, para); } catch (eW) {}
  var items = [];
  var netErr = '';
  try { items = qdDirectCmt.call(this, bid, cid, segUsed); } catch (e0) { netErr = String(e0.message || e0); items = []; }

  /* 2) 真实 ID 取不到，再试原值（可能本来就是真实 ID） */
  if (!items.length && String(segUsed) !== String(para)) {
    try {
      var alt = qdDirectCmt.call(this, bid, cid, String(para));
      if (alt.length) { items = alt; segUsed = String(para); }
    } catch (e1) {}
  }

  /* 3) 点的本来就是章评（-1/0）才取章评；否则绝不回退，避免各段内容雷同 */
  if (!items.length) {
    var isChapter = (String(para) === '-1' || String(para) === '0');
    if (isChapter) {
      try { items = qdDirectCmt.call(this, bid, cid, '-1'); } catch (e2) {}
      if (items.length) segUsed = '-1';
    }
  }

  var html = '';
  if (items.length) {
    /* 保留层级交给面板折叠展示；仅在接口未返回内嵌回复时才展平 */
    try {
      var hasNested = false;
      for (var hn = 0; hn < items.length && !hasNested; hn++) {
        for (var hk = 0; hk < QD_REPLY_KEYS.length; hk++) {
          var sv = items[hn][QD_REPLY_KEYS[hk]];
          if (sv && qdIsArr(sv) && sv.length) { hasNested = true; break; }
        }
      }
      if (!hasNested) {
        var flat = qdFlatten(items, 0);
        if (flat.length > items.length) items = flat;
      }
    } catch (eF) {}
    /* 面板 HTML 短时缓存：同一段反复点开不再重新渲染（5 分钟内） */
    html = qdHtmlGet(this, bid, cid, segUsed);
    if (!html) {
      html = qdCmtPanel.call(this, bid, cid, segUsed, items, title, para, _wantN);
      if (html) qdHtmlPut(this, bid, cid, segUsed, html);
    }
  } else {
    /* 3) 直连也没有：先看服务器页，服务器页也是外壳就给明确提示 */
    var server = '';
    try { server = String(java.ajax(url) || ''); } catch (e3) {}
    if (!netErr && QD_LAST_NET_ERR) netErr = QD_LAST_NET_ERR;
    if (!netErr && !server) netErr = 'java.net: \u63a5\u53e3\u65e0\u54cd\u5e94';
    html = qdShellOnly(server)
      ? qdCmtEmptyPanel(para, title, 'type\u4e0e\u53c2\u6570\u540d\u5404\u79cd', netErr)
      : server;
  }

  /* 记录本次面板，供 3 秒内的重复点击复用 */
  if (html) qdClickGuardPut(this, bid, cid, para, html);

  var cfg = null;
  try { cfg = qdHalfCfg.call(this); } catch (e4) {}
  if (cfg) java.showBrowser(url, html, qdPreJs(), cfg);
  else java.showBrowser(url, html, qdPreJs());
  } finally {
    qdBusyClear(this, bid, cid, para);
  }
}

function showCmt(bid, cid, para, date, dev, bbpd) {
