    try { var title = cache.getFromMemory(mname + '-text') ?? '起点段评'; var url = qt + '/comments?bookId=' + bid + '&chapterId=' + cid + '&paragraphId=' + para + '&text=' + encodeURIComponent(title) + this.appSession(); try { qdOpenCmtFb.call(this, url + '&mode=popup', bid, cid, para, title); } catch (e2) { java.startBrowser(url, title); } } catch (error) { java.log('获取或处理评论失败: ' + error); }
}
function androidshowCmt(bid, cid, para, date, dev, bbpd) {
