   书源走不了起点账密登录（验证码+风控），改为让用户在浏览器登录后复制 Cookie。 */
function qdPick(v) {
  try { return String((typeof result !== 'undefined' && result ? result[v] : '') || ''); } catch (e) { return ''; }
}

/* 清洗粘贴进来的 Cookie：去换行、去 "Cookie:" 前缀、去首尾空格 */
function qdCleanCookie(raw) {
  var t = String(raw || '');
  t = t.replace(/^[\s\S]*?[Cc]ookie\s*[:：]\s*/, '');
  t = t.replace(/[\r\n]+/g, ' ').replace(/\s+/g, ' ').replace(/^\s+|\s+$/g, '');
  t = t.replace(/;\s*;/g, ';').replace(/^;|;$/g, '').trim();
  return t;
}

function saveQdLogin() {
