    'Cookie: ' + (ck ? ck.length + ' 字节' : '未填') + '\n' +
    'ywkey: ' + (ywkey ? '已填' : '未填') + ' / ywguid: ' + (ywguid ? '已填' : '未填') + '\n' +
    '识别到的登录标记: ' + (st.marks.length ? st.marks.join(',') : '无');
  try { java.longToast(msg); } catch (e7) { try { java.toast('已保存'); } catch (e8) {} }
  try { qdSaveLoginInfo({ '起点Cookie': ck }); } catch (e9) {}
