/* 起点登录态检测：直接打起点接口看返回 */
function qdLoginCheck() {
  var c = qdCtx();
  var lines = [];
  try { qdEnsureToken.call(c); } catch (e) {}
  try { qdApplyCookie.call(c); } catch (e2) {}
  var st = { marks: [], cookieLength: 0 };
  try { st = qdLoginState.call(c); } catch (e3) {}
  lines.push('① Cookie: ' + (st.cookieLength ? st.cookieLength + ' 字节' : '空'));
  lines.push('② 登录标记: ' + (st.marks.length ? st.marks.join(',') : '无（游客态，付费段评可能取不到）'));
  var tk = '';
  try { tk = qdCsrfOf(c); } catch (e4) {}
  lines.push('③ csrf: ' + (tk ? tk.slice(0, 10) + '…' : '未取到'));
  try {
    var raw = String(c.java.ajax('https://m.qidian.com/majax/chapterReview/reviewSummary?bookId=1209977&chapterId=1&_csrfToken=' + encodeURIComponent(tk) + ',{"headers":{"Cookie":"' + qdCookieOf(c) + '"}}') || '');
    var j = JSON.parse(raw);
    var d = j && j.data ? j.data : {};
    var list = d.list || [];
    lines.push('④ 起点应答: ' + (list.length ? ('段数=' + list.length) : ('code=' + (j && j.code) + ' ' + String(raw).slice(0, 50))));
  } catch (e5) {
    lines.push('④ 起点应答: 异常 ' + String(e5.message || e5).slice(0, 50));
