/* ===== 一键登录：内置浏览器打开起点 → 关闭后自动读取 Cookie ===== */
var QD_LOGIN_URL = 'https://m.qidian.com/login';

/* 从 cookie jar 里挑出最完整的一串（含起点登录标记的优先） */
function qdReadCookieFromJar() {
  var c = qdCtx();
  var doms = ['https://m.qidian.com', 'https://www.qidian.com', 'https://qidian.com', 'https://vipreader.qidian.com'];
  var best = '';
  var bestScore = -1;
  for (var i = 0; i < doms.length; i++) {
    var ck = '';
    try { ck = String(c.cookie.getCookie(doms[i]) || ''); } catch (e) {}
    if (!ck) continue;
    var score = 0;
    if (/ywguid\s*=/.test(ck)) score += 10;
    if (/ywkey\s*=/.test(ck)) score += 10;
    if (/user_id\s*=/.test(ck)) score += 8;
    if (/w_tsfp\s*=/.test(ck)) score += 6;
    if (/qdrs\s*=/.test(ck)) score += 6;
    if (/tk\s*=/.test(ck)) score += 4;
    if (/_csrfToken\s*=/.test(ck)) score += 2;
    if (score > bestScore) { bestScore = score; best = ck; }
  }
  return best;
}

/* 一键登录：打开起点登录页，等用户关闭后自动保存 */
function qdLoginWeb() {
  var c = qdCtx();
  var opened = false;
  try {
    java.startBrowserAwait(QD_LOGIN_URL, '登录起点（登录后关闭本页）');
    opened = true;
  } catch (e) {
    opened = false;
  }
  if (!opened) {
    try { java.startBrowser(QD_LOGIN_URL, '登录起点'); } catch (e2) {}
    try { java.toast('已打开起点登录页，登录后回来点「我已登录，读取Cookie」'); } catch (e3) {}
    return '';
  }
  return qdSaveCookieFromJar();
}

/* 用户手动关闭后，点这个按钮读取 */
function qdSaveCookieFromJar() {
  var c = qdCtx();
  var ck = '';
  try { ck = qdReadCookieFromJar(); } catch (e) {}
  if (!ck) {
    try { java.longToast('未读到起点 Cookie。\n请确认已在打开的页面里登录起点，\n然后回来再点一次本按钮。'); } catch (e2) {}
    return '';
  }
  ck = qdCleanCookie(ck);
  try { c.source.put('qd_ck', ck); } catch (e3) {}
  try { qdApplyCookie.call(c); } catch (e4) {}
  var st = { marks: [], cookieLength: 0 };
  try { st = qdLoginState.call(c); } catch (e5) {}
  var logged = /ywguid\s*=/.test(ck) || /user_id\s*=/.test(ck) || /ywkey\s*=/.test(ck);
  var msg = (logged ? '✅ 已读取到起点登录态' : '⚠️ 读到 Cookie，但没发现登录标记（可能没登录）') +
    '\nCookie: ' + ck.length + ' 字节\n标记: ' + (st.marks.length ? st.marks.join(',') : '无');
  try { java.longToast(msg); } catch (e6) {}
  try { qdSaveLoginInfo({ '起点Cookie': ck }); } catch (e7) {}
  return ck;
}

/* ===== 把诊断结果交给用户：复制 / 查看 ===== */
function qdCopyText(text) {
