    var data = result;
    if (typeof data === 'string') data = JSON.parse(data);
    if (!data || data.code != 1 || !data.data) return [];
    var host = String(java.get('source') || '');
    var bookid = String(java.get('bookid') || '');
    var rawStr = String(data.data || '').trim();
    if (!rawStr) return [];
    var chapters = rawStr.split('-//-');
    var titleSource = null;
    if (data.oridata && String(data.oridata).trim().length > 0) {
      titleSource = String(data.oridata).trim().split('-//-');
    } else if (data.enckey) {
      try { titleSource = java.base64Decode(String(data.enckey)).split('-//-'); } catch(e) {}
    }
    // 网页版判定：da[1] in x.unlocked 才算已解锁（空表 = 一章都没解锁）
    var unlockedMap = null;
    if (data.unlocked && typeof data.unlocked === 'object') {
      unlockedMap = {};
      for (var k in data.unlocked) {
        unlockedMap[String(k)] = true;
      }
    }
    var unvipCount = data.unvip ? parseInt(data.unvip) : chapters.length;
    var list = [];
    for (var i = 0; i < chapters.length; i++) {
      var parts = chapters[i].split('-/-');
      if (parts.length < 3) continue;
      var cid = String(parts[1]);
      var title = String(parts[2]);
      if (titleSource && i < titleSource.length) {
        var tsParts = titleSource[i].split('-/-');
        if (tsParts.length >= 3 && String(tsParts[2]).length > 0) title = String(tsParts[2]);
      }
      var isVip = parts.length > 3 ? String(parts[3]).trim().toLowerCase() !== 'unvip' : i >= unvipCount;
      var isUnlocked = false;
      if (unlockedMap) {
        try { isUnlocked = Object.prototype.hasOwnProperty.call(unlockedMap, cid); } catch (eU) { isUnlocked = false; }
      }
      var isLocked = isVip && !isUnlocked;
      if (isLocked) title = '🔒' + title;
      var url = String('https://xianren.127169.xyz/content?host=' + host + '&bookId=' + bookid + '&chapterId=' + cid);
      list.push({ chapterUrl: url, chapterName: title });
    }
    return list;
  } catch(e) { return []; }
})()

